:root {
  --bg: #eef6ff;
  --bg-2: #f8fbff;
  --card: rgba(255, 255, 255, 0.92);
  --solid-card: #ffffff;
  --text: #17324d;
  --muted: #64748b;
  --primary: #2563eb;
  --primary-dark: #1d4ed8;
  --primary-soft: #dbeafe;
  --success: #16a34a;
  --success-soft: #dcfce7;
  --warning: #f59e0b;
  --danger: #dc2626;
  --danger-soft: #fee2e2;
  --line: #d7e3f3;
  --line-strong: #bfdbfe;
  --editor-bg: #ffffff;
  --editor-gutter: #f1f5f9;
  --editor-text: #0f172a;
  --editor-line: #64748b;
  --shadow: 0 18px 45px rgba(37, 99, 235, 0.14);
  --shadow-strong: 0 24px 70px rgba(15, 23, 42, 0.24);
  --radius: 22px;
}

[data-theme="dark"] {
  --bg: #07111f;
  --bg-2: #0f172a;
  --card: rgba(15, 23, 42, 0.9);
  --solid-card: #111827;
  --text: #e5edf7;
  --muted: #a7b4c7;
  --primary: #60a5fa;
  --primary-dark: #93c5fd;
  --primary-soft: rgba(37, 99, 235, 0.22);
  --success: #4ade80;
  --success-soft: rgba(22, 163, 74, 0.18);
  --warning: #fbbf24;
  --danger: #fb7185;
  --danger-soft: rgba(220, 38, 38, 0.15);
  --line: #243247;
  --line-strong: #334155;
  --editor-bg: #020617;
  --editor-gutter: #030712;
  --editor-text: #f8fafc;
  --editor-line: #94a3b8;
  --shadow: 0 18px 45px rgba(0, 0, 0, 0.28);
  --shadow-strong: 0 24px 80px rgba(0, 0, 0, 0.5);
}

* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  min-height: 100vh;
  font-family: Inter, Segoe UI, Arial, sans-serif;
  color: var(--text);
  background:
    radial-gradient(circle at top left, rgba(96, 165, 250, 0.34), transparent 34rem),
    radial-gradient(circle at bottom right, rgba(34, 197, 94, 0.14), transparent 28rem),
    linear-gradient(135deg, var(--bg) 0%, var(--bg-2) 54%, var(--bg) 100%);
}

button,
textarea,
input,
select {
  font: inherit;
}

button {
  user-select: none;
}

.app-shell {
  width: min(1480px, calc(100% - 32px));
  margin: 0 auto;
  padding: 28px 0 34px;
}

.topbar,
.activity-card,
.panel,
.help-card {
  border: 1px solid rgba(215, 227, 243, 0.86);
  border-color: var(--line);
  border-radius: var(--radius);
  background: var(--card);
  box-shadow: var(--shadow-soft);
  backdrop-filter: blur(10px);
}

.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  padding: 24px;
}

.brand-block {
  display: flex;
  align-items: center;
  gap: 16px;
}

.logo-mark {
  display: grid;
  place-items: center;
  flex: 0 0 58px;
  width: 58px;
  height: 58px;
  border-radius: 20px;
  color: white;
  background: linear-gradient(135deg, var(--primary), #06b6d4 54%, var(--success));
  box-shadow: 0 16px 34px rgba(37, 99, 235, 0.28);
  font-size: 1.1rem;
  font-weight: 1000;
}

.eyebrow,
.section-kicker {
  margin: 0 0 8px;
  color: var(--primary);
  font-size: 0.76rem;
  font-weight: 900;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

h1,
h2,
h3,
p {
  margin-top: 0;
}

h1 {
  margin-bottom: 8px;
  font-size: clamp(1.9rem, 4vw, 3.2rem);
  line-height: 1.02;
}

h2 {
  margin-bottom: 6px;
}

h3 {
  margin-bottom: 8px;
}

.subtitle,
.panel-header p,
.muted-text {
  margin-bottom: 0;
  color: var(--muted);
}

.top-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  justify-content: flex-end;
}

.primary-btn,
.success-btn,
.ghost-btn,
.icon-btn {
  min-height: 42px;
  border: 0;
  border-radius: 999px;
  padding: 0 18px;
  font-weight: 900;
  cursor: pointer;
  transition: transform 0.15s ease, box-shadow 0.15s ease, background 0.15s ease, border 0.15s ease;
}

.primary-btn {
  color: white;
  background: linear-gradient(135deg, #2563eb, #06b6d4);
  box-shadow: 0 10px 22px rgba(37, 99, 235, 0.28);
}

.success-btn {
  color: white;
  background: linear-gradient(135deg, #16a34a, #22c55e);
  box-shadow: 0 10px 22px rgba(22, 163, 74, 0.22);
}

.ghost-btn,
.icon-btn {
  color: var(--text);
  border: 1px solid var(--line);
  background: var(--solid-card);
}

.ghost-btn.danger {
  color: var(--danger);
}

.primary-btn:hover,
.success-btn:hover,
.ghost-btn:hover,
.icon-btn:hover {
  transform: translateY(-1px);
  box-shadow: 0 12px 24px rgba(15, 23, 42, 0.12);
}

.activity-card {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  margin-top: 20px;
  padding: 20px 22px;
}

.activity-stats {
  display: flex;
  gap: 12px;
}

.activity-stats > div {
  min-width: 112px;
  border: 1px solid var(--line);
  border-radius: 18px;
  padding: 14px;
  text-align: center;
  background: var(--solid-card);
}

.stat-number {
  display: block;
  color: var(--primary);
  font-size: 1.65rem;
  font-weight: 1000;
  line-height: 1;
}

.stat-label {
  display: block;
  margin-top: 4px;
  color: var(--muted);
  font-size: 0.8rem;
  font-weight: 800;
}

.workspace {
  display: grid;
  grid-template-columns: minmax(0, 1.07fr) minmax(380px, 0.93fr);
  gap: 20px;
  margin-top: 20px;
}

.panel,
.help-card {
  overflow: hidden;
}

.panel-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  padding: 18px 20px;
  border-bottom: 1px solid var(--line);
}

.panel-header h2 {
  margin-bottom: 4px;
  font-size: 1.1rem;
}

.compact-header {
  padding: 16px 18px;
}

.status-badge {
  flex: none;
  border-radius: 999px;
  padding: 7px 12px;
  color: var(--primary-dark);
  background: var(--primary-soft);
  font-size: 0.82rem;
  font-weight: 900;
}

.language-tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  padding: 14px 18px 0;
  background: color-mix(in srgb, var(--solid-card) 92%, var(--primary-soft));
}

.tab-btn {
  border: 1px solid var(--line);
  border-bottom-color: transparent;
  border-radius: 14px 14px 0 0;
  padding: 11px 18px;
  color: var(--muted);
  background: var(--solid-card);
  font-weight: 1000;
  cursor: pointer;
}

.tab-btn.active {
  color: white;
  border-color: transparent;
  background: linear-gradient(135deg, #2563eb, #06b6d4);
}

.editor-info {
  padding: 10px 18px 14px;
  color: var(--muted);
  background: color-mix(in srgb, var(--solid-card) 92%, var(--primary-soft));
  border-bottom: 1px solid var(--line);
  font-size: 0.92rem;
}

.editor-wrap {
  position: relative;
  display: grid;
  grid-template-columns: 54px minmax(0, 1fr);
  min-height: max(560px, 72vh);
  background: var(--editor-bg);
}

.line-numbers {
  min-height: max(560px, 72vh);
  padding: 18px 10px;
  color: var(--editor-line);
  border-right: 1px solid rgba(148, 163, 184, 0.18);
  background: var(--editor-gutter);
  font: var(--editor-font-size, 15px)/1.65 Consolas, Monaco, Courier New, monospace;
  text-align: right;
  white-space: pre;
  user-select: none;
  overflow: hidden;
}

.editor-stack {
  position: relative;
  min-width: 0;
  min-height: max(560px, 72vh);
  background: var(--editor-bg);
}

#codeEditor,
.code-match-layer {
  width: 100%;
  min-height: max(560px, 72vh);
  padding: 18px;
  font: var(--editor-font-size, 15px)/1.65 Consolas, Monaco, Courier New, monospace;
  tab-size: 2;
  white-space: pre-wrap;
  overflow-wrap: break-word;
}

#codeEditor {
  position: relative;
  z-index: 2;
  display: block;
  resize: none;
  overflow: hidden;
  border: 0;
  outline: none;
  color: var(--editor-text);
  background: transparent;
}

.code-match-layer {
  position: absolute;
  inset: 0;
  z-index: 1;
  color: transparent;
  pointer-events: none;
  overflow: hidden;
  scrollbar-width: none;
}

.code-match-layer::-webkit-scrollbar {
  display: none;
}

.code-match-layer .tag-match {
  border-radius: 5px;
  color: transparent;
  text-decoration-line: underline;
  text-decoration-thickness: 3px;
  text-underline-offset: 4px;
}

.code-match-layer .tag-match-pair {
  background: rgba(37, 99, 235, 0.14);
  text-decoration-color: #2563eb;
}

.code-match-layer .tag-match-missing {
  background: rgba(239, 68, 68, 0.14);
  text-decoration-color: #ef4444;
  text-decoration-style: wavy;
}

.code-match-layer .tag-match-self {
  background: rgba(22, 163, 74, 0.14);
  text-decoration-color: #16a34a;
}

#codeEditor::selection {
  background: rgba(96, 165, 250, 0.35);
}

/* Theme-aware editor surface */
:root #codeEditor {
  caret-color: #0f172a;
}

[data-theme="dark"] #codeEditor {
  caret-color: #f8fafc;
}

:root .editor-wrap,
:root .editor-stack {
  box-shadow: inset 0 0 0 1px rgba(148, 163, 184, 0.16);
}

[data-theme="dark"] .editor-wrap,
[data-theme="dark"] .editor-stack {
  box-shadow: none;
}

.tips-row {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 10px;
  padding: 12px 18px;
  color: var(--muted);
  border-top: 1px solid var(--line);
  background: var(--solid-card);
  font-size: 0.9rem;
}

kbd {
  border: 1px solid var(--line-strong);
  border-bottom-width: 2px;
  border-radius: 6px;
  padding: 2px 6px;
  color: var(--text);
  background: var(--solid-card);
  font-size: 0.78rem;
  font-weight: 900;
}

.suggestion-box {
  position: absolute;
  z-index: 10;
  left: 18px;
  top: 54px;
  width: min(390px, calc(100% - 36px));
  max-height: 270px;
  overflow-y: auto;
  border: 1px solid rgba(147, 197, 253, 0.6);
  border-radius: 16px;
  background: #ffffff;
  box-shadow: 0 20px 35px rgba(15, 23, 42, 0.22);
}

.suggestion-box.hidden,
.hidden {
  display: none !important;
}

.suggestion-item {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 12px;
  width: 100%;
  padding: 11px 13px;
  border-bottom: 1px solid #e2e8f0;
  color: #172554;
  cursor: pointer;
}

.suggestion-item:last-child {
  border-bottom: 0;
}

.suggestion-item:hover,
.suggestion-item.active {
  background: #eff6ff;
}

.suggestion-label {
  font-weight: 1000;
}

.suggestion-desc {
  color: #64748b;
  font-size: 0.82rem;
}

.suggestion-type {
  align-self: start;
  border-radius: 999px;
  padding: 3px 8px;
  color: #1d4ed8;
  background: #dbeafe;
  font-size: 0.72rem;
  font-weight: 1000;
}

.right-column {
  display: grid;
  gap: 20px;
  align-content: start;
}

.preview-panel {
  min-height: 100%;
}

#previewFrame {
  display: block;
  width: 100%;
  min-height: 390px;
  border: 0;
  background: white;
}

.result-content {
  padding: 18px;
}

.empty-state {
  display: grid;
  place-items: center;
  min-height: 250px;
  text-align: center;
  color: var(--muted);
}

.empty-state h3 {
  color: var(--text);
}

.empty-icon {
  display: grid;
  place-items: center;
  width: 58px;
  height: 58px;
  margin-bottom: 8px;
  border-radius: 20px;
  color: var(--success);
  background: var(--success-soft);
  font-size: 1.5rem;
  font-weight: 1000;
}

.score-card {
  display: grid;
  gap: 14px;
}

.score-main {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  border: 1px solid var(--line);
  border-radius: 20px;
  padding: 18px;
  background: var(--solid-card);
}

.score-number {
  font-size: clamp(2rem, 5vw, 3.4rem);
  line-height: 1;
  font-weight: 1000;
  color: var(--primary);
}

.score-number small {
  color: var(--muted);
  font-size: 1rem;
}

.score-pill {
  border-radius: 999px;
  padding: 8px 12px;
  font-weight: 1000;
  color: #166534;
  background: #dcfce7;
}

.score-pill.needs-work {
  color: #991b1b;
  background: #fee2e2;
}

.score-pill.almost {
  color: #92400e;
  background: #fef3c7;
}

.feedback-box {
  border: 1px solid var(--line);
  border-radius: 18px;
  padding: 14px;
  color: var(--text);
  background: color-mix(in srgb, var(--solid-card) 86%, var(--primary-soft));
}

.rubric-list {
  display: grid;
  gap: 10px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.rubric-item {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: start;
  gap: 10px;
  border: 1px solid var(--line);
  border-radius: 16px;
  padding: 12px;
  background: var(--solid-card);
}

.rubric-check {
  display: grid;
  place-items: center;
  width: 28px;
  height: 28px;
  border-radius: 999px;
  color: white;
  background: var(--success);
  font-weight: 1000;
}

.rubric-check.fail {
  background: var(--danger);
}

.rubric-title {
  margin: 0;
  font-weight: 900;
}

.rubric-rule {
  margin-top: 3px;
  color: var(--muted);
  font-size: 0.84rem;
}

.rubric-points {
  font-weight: 1000;
  color: var(--primary);
  white-space: nowrap;
}

.help-card {
  margin-top: 20px;
  padding: 18px 20px;
}

.help-header {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 12px;
}

.help-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 12px;
}

.help-grid > div {
  border: 1px solid var(--line);
  border-radius: 16px;
  padding: 14px;
  color: var(--muted);
  background: var(--solid-card);
}

code {
  border-radius: 6px;
  padding: 2px 5px;
  color: var(--primary-dark);
  background: var(--primary-soft);
  font-family: Consolas, Monaco, Courier New, monospace;
}

.modal-overlay {
  position: fixed;
  inset: 0;
  z-index: 50;
  display: grid;
  place-items: center;
  padding: 20px;
  background: rgba(2, 6, 23, 0.66);
}

.admin-modal {
  width: min(980px, 100%);
  max-height: min(92vh, 900px);
  overflow: auto;
  border: 1px solid var(--line);
  border-radius: 24px;
  background: var(--solid-card);
  box-shadow: var(--shadow-strong);
}

.modal-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  padding: 20px;
  border-bottom: 1px solid var(--line);
}

.icon-btn {
  display: grid;
  place-items: center;
  width: 42px;
  height: 42px;
  padding: 0;
  font-size: 1.6rem;
}

.pin-screen,
.admin-form {
  display: grid;
  gap: 16px;
  padding: 20px;
}

.pin-row {
  display: flex;
  gap: 10px;
}

label {
  display: grid;
  gap: 7px;
  color: var(--text);
  font-weight: 900;
}

input,
textarea,
select {
  width: 100%;
  border: 1px solid var(--line-strong);
  border-radius: 14px;
  padding: 12px 13px;
  color: var(--text);
  background: var(--solid-card);
  outline: none;
}

textarea {
  resize: vertical;
}

input:focus,
textarea:focus,
select:focus {
  border-color: var(--primary);
  box-shadow: 0 0 0 4px var(--primary-soft);
}

.helper-note {
  margin: 0;
  color: var(--muted);
  font-size: 0.92rem;
}

.form-grid {
  display: grid;
  grid-template-columns: 1.4fr 0.6fr;
  gap: 14px;
}

.rubric-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  border-top: 1px solid var(--line);
  padding-top: 16px;
}

.criteria-editor {
  display: grid;
  gap: 12px;
}

.criterion-card {
  border: 1px solid var(--line);
  border-radius: 18px;
  padding: 14px;
  background: color-mix(in srgb, var(--solid-card) 92%, var(--primary-soft));
}

.criterion-grid {
  display: grid;
  grid-template-columns: 1.3fr 0.4fr 1fr 1fr auto;
  gap: 10px;
  align-items: end;
}

.remove-criterion {
  width: 42px;
  height: 42px;
  min-height: 42px;
  padding: 0;
}

.admin-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 10px;
  border-top: 1px solid var(--line);
  padding-top: 16px;
}

@media (max-width: 1100px) {
  .topbar,
  .activity-card,
  .panel-header {
    align-items: flex-start;
    flex-direction: column;
  }

  .top-actions,
  .activity-stats {
    width: 100%;
    justify-content: flex-start;
  }

  .workspace,
  .help-grid {
    grid-template-columns: 1fr;
  }

  #previewFrame {
    min-height: 430px;
  }
}

@media (max-width: 760px) {
  .brand-block {
    align-items: flex-start;
  }

  .top-actions > button {
    flex: 1 1 150px;
  }

  .activity-stats {
    display: grid;
    grid-template-columns: 1fr 1fr;
  }

  .form-grid,
  .criterion-grid {
    grid-template-columns: 1fr;
  }

  .pin-row {
    flex-direction: column;
  }

  .score-main {
    align-items: flex-start;
    flex-direction: column;
  }
}

@media (max-width: 560px) {
  .app-shell {
    width: min(100% - 18px, 1480px);
    padding-top: 10px;
  }

  .topbar,
  .activity-card,
  .panel,
  .help-card,
  .admin-modal {
    border-radius: 18px;
  }

  .logo-mark {
    display: none;
  }

  .editor-wrap {
    grid-template-columns: 42px minmax(0, 1fr);
  }

  .line-numbers {
    padding-left: 6px;
    padding-right: 7px;
  }

  #codeEditor,
  .code-match-layer {
    padding: 14px;
    font-size: var(--editor-font-size, 15px);
  }

  .suggestion-box {
    left: 14px;
    width: calc(100% - 28px);
  }

  .tab-btn {
    flex: 1 1 auto;
    padding-inline: 10px;
  }

  .rubric-item {
    grid-template-columns: auto 1fr;
  }

  .rubric-points {
    grid-column: 2;
  }
}

/* Version 2 additions: full HTML checker, richer suggestions, and flexible preview layouts */
.structure-alert {
  border-bottom: 1px solid var(--line);
  padding: 12px 18px;
  background: var(--solid-card);
}

.structure-alert.good {
  background: color-mix(in srgb, var(--success-soft) 68%, var(--solid-card));
}

.structure-alert.warning {
  background: color-mix(in srgb, var(--danger-soft) 58%, var(--solid-card));
}

.structure-message {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 14px;
  align-items: center;
  margin-bottom: 10px;
  color: var(--text);
}

.structure-message span {
  color: var(--muted);
  font-size: 0.9rem;
}

.structure-list {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
}

.structure-chip {
  border-radius: 999px;
  padding: 5px 9px;
  font-size: 0.78rem;
  font-weight: 1000;
}

.structure-chip.pass {
  color: #166534;
  background: #dcfce7;
}

.structure-chip.missing {
  color: #991b1b;
  background: #fee2e2;
}

.preview-header {
  align-items: flex-start;
}

.preview-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 8px;
}

.layout-btn {
  border: 1px solid var(--line);
  border-radius: 999px;
  padding: 8px 11px;
  color: var(--muted);
  background: var(--solid-card);
  font-size: 0.8rem;
  font-weight: 1000;
  cursor: pointer;
}

.layout-btn:hover,
.layout-btn.active {
  color: white;
  border-color: transparent;
  background: linear-gradient(135deg, var(--primary), #06b6d4);
}

.layout-btn.strong {
  color: #14532d;
  border-color: #bbf7d0;
  background: #dcfce7;
}

.layout-btn.danger {
  color: #991b1b;
  border-color: #fecaca;
