/* Scale-based rubric builder */
.scale-criterion-card {
  display: grid;
  gap: 14px;
}

.criterion-header-row {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 12px;
}

.criterion-title-big {
  margin-top: 6px;
  font-size: 1.02rem;
  font-weight: 800;
}

.compact-criterion-grid {
  grid-template-columns: 0.6fr 1.2fr 1fr;
}

.scale-rubric-table {
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 16px;
  background: var(--solid-card);
}

.scale-rubric-head,
.scale-level-row {
  display: grid;
  grid-template-columns: 170px 110px 1fr;
  gap: 10px;
  align-items: center;
}

.scale-rubric-head {
  padding: 10px 12px;
  font-size: 0.78rem;
  font-weight: 900;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--muted);
  background: color-mix(in srgb, var(--solid-card) 78%, var(--primary-soft));
}

.scale-level-row {
  padding: 12px;
  border-top: 1px solid var(--line);
}

.scale-level-name {
  font-weight: 900;
  color: var(--text);
}

.scale-level-row label {
  gap: 5px;
}

.level-description-label textarea {
  resize: vertical;
  min-height: 54px;
}

.scale-result-item.excellent {
  border-left: 5px solid #22c55e;
}

.scale-result-item.good {
  border-left: 5px solid #38bdf8;
}

.scale-result-item.fair {
  border-left: 5px solid #f59e0b;
}

.scale-result-item.needsImprovement {
  border-left: 5px solid #ef4444;
}

@media (max-width: 820px) {
  .criterion-header-row,
  .rubric-toolbar {
    flex-direction: column;
    align-items: stretch;
  }

  .compact-criterion-grid,
  .scale-rubric-head,
  .scale-level-row {
    grid-template-columns: 1fr;
  }

  .scale-rubric-head {
    display: none;
  }
}


/* Version 12: teacher rubric table input */
.rubric-table-note {
  border: 1px solid var(--line);
  border-radius: 16px;
  padding: 12px 14px;
  background: color-mix(in srgb, var(--solid-card) 82%, var(--primary-soft));
