  padding: 14px;
  background: color-mix(in srgb, var(--solid-card) 92%, var(--primary-soft));
}

.rubric-level-cell {
  min-width: 190px;
  padding: 12px;
}

.criterion-title-row {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 10px;
  align-items: center;
  margin-bottom: 10px;
}

.criterion-number {
  display: inline-grid;
  place-items: center;
  width: 34px;
  height: 34px;
  border-radius: 12px;
