/* Error Checker Panel */
.error-checker-panel {
  overflow: hidden;
}

.error-checker-header {
  align-items: center;
}

.error-checker-content {
  display: grid;
  gap: 12px;
  padding: 14px;
}

.checker-empty {
  display: grid;
  gap: 4px;
  border: 1px dashed var(--line-strong);
  border-radius: 16px;
  padding: 14px;
  color: var(--muted);
  background: color-mix(in srgb, var(--solid-card) 86%, var(--primary-soft));
}

.checker-empty strong {
  color: var(--text);
}

.checker-summary {
  border: 1px solid var(--line);
  border-radius: 18px;
  padding: 14px;
  background: var(--solid-card);
}

.checker-summary strong {
  display: block;
  margin-bottom: 3px;
  color: var(--text);
  font-size: 1rem;
}

.checker-summary span {
  color: var(--muted);
  font-size: 0.88rem;
}

.checker-summary.pass {
  border-color: color-mix(in srgb, var(--success) 42%, var(--line));
  background: color-mix(in srgb, var(--success-soft) 64%, var(--solid-card));
}

.checker-summary.warning {
  border-color: color-mix(in srgb, var(--warning) 42%, var(--line));
  background: color-mix(in srgb, #fef3c7 56%, var(--solid-card));
}

.checker-summary.error {
  border-color: color-mix(in srgb, var(--danger) 42%, var(--line));
  background: color-mix(in srgb, var(--danger-soft) 56%, var(--solid-card));
}

.checker-list {
  display: grid;
  gap: 9px;
}

.checker-item {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 10px;
  align-items: start;
  border: 1px solid var(--line);
  border-radius: 16px;
  padding: 12px;
  background: var(--solid-card);
}

.checker-icon {
  display: grid;
  place-items: center;
  width: 30px;
  height: 30px;
  border-radius: 999px;
  color: white;
  background: var(--primary);
  font-size: 0.9rem;
  font-weight: 1000;
}

.checker-item.pass .checker-icon {
  background: var(--success);
}

.checker-item.error .checker-icon {
  background: var(--danger);
}

.checker-item.warning .checker-icon {
  color: #78350f;
  background: #fbbf24;
}

.checker-item.tip .checker-icon {
  background: #0ea5e9;
}

.checker-item h3 {
  margin: 0 0 3px;
  font-size: 0.95rem;
}

.checker-item p {
  margin: 0;
  color: var(--muted);
  font-size: 0.88rem;
  line-height: 1.35;
}

.checker-item small {
  display: block;
  margin-top: 6px;
  color: var(--text);
  font-weight: 800;
  line-height: 1.35;
}

.checker-item.pass {
  border-left: 5px solid var(--success);
}

.checker-item.warning {
  border-left: 5px solid var(--warning);
}

.checker-item.error {
  border-left: 5px solid var(--danger);
}

.checker-item.tip {
  border-left: 5px solid #0ea5e9;
}

[data-theme="dark"] .checker-summary.warning {
  background: rgba(245, 158, 11, 0.16);
}

[data-theme="dark"] .checker-summary.pass {
  background: rgba(22, 163, 74, 0.16);
}

[data-theme="dark"] .checker-summary.error {
  background: rgba(220, 38, 38, 0.16);
}

@media (max-width: 760px) {
  .error-checker-content {
    padding: 12px;
  }

  .checker-item {
    border-radius: 14px;
    padding: 10px;
  }

  .checker-item h3 {
    font-size: 0.9rem;
  }

  .checker-item p,
  .checker-item small {
    font-size: 0.82rem;
  }
}


/* AI Review Panel additions */
.ai-review-panel {
  border-color: color-mix(in srgb, var(--primary) 34%, var(--line));
}

.ai-review-header {
  background: linear-gradient(135deg, color-mix(in srgb, var(--solid-card) 88%, var(--primary-soft)), var(--solid-card));
}

.ai-review-content {
  padding: 18px;
}

.empty-ai-review {
  display: grid;
  place-items: center;
  min-height: 220px;
  text-align: center;
  color: var(--muted);
}

.ai-empty-icon {
  display: grid;
  place-items: center;
  width: 58px;
  height: 58px;
  margin-bottom: 8px;
  border-radius: 20px;
  color: #7c3aed;
  background: color-mix(in srgb, #ede9fe 80%, var(--solid-card));
  font-size: 1.45rem;
  font-weight: 1000;
}

.ai-small-note {
  max-width: 520px;
  margin: 6px auto 0;
  color: var(--muted);
  font-size: 0.9rem;
}

.ai-review-card {
  display: grid;
  gap: 14px;
}

.ai-review-main {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  border: 1px solid var(--line);
  border-radius: 20px;
  padding: 16px;
  background: linear-gradient(135deg, color-mix(in srgb, var(--solid-card) 82%, var(--primary-soft)), var(--solid-card));
}

.ai-review-main h3 {
  margin-bottom: 6px;
  line-height: 1.25;
}

.ai-badge {
  display: grid;
  place-items: center;
  flex: 0 0 42px;
  width: 42px;
  height: 42px;
  border-radius: 16px;
  color: white;
  background: linear-gradient(135deg, #7c3aed, #06b6d4);
  font-weight: 1000;
  box-shadow: 0 12px 28px rgba(124, 58, 237, 0.24);
}

.ai-review-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 12px;
}

.ai-review-block {
  border: 1px solid var(--line);
  border-radius: 18px;
  padding: 14px;
  background: var(--solid-card);
}

.ai-review-block h4 {
  margin: 0 0 10px;
  color: var(--text);
}

.ai-review-block ul {
  display: grid;
  gap: 8px;
  margin: 0;
  padding-left: 18px;
  color: var(--muted);
  line-height: 1.4;
}

.ai-review-block.good {
  border-left: 5px solid #22c55e;
}

.ai-review-block.improve {
  border-left: 5px solid #f59e0b;
}

.ai-review-block.steps {
  border-left: 5px solid #06b6d4;
}

.ai-note {
  border: 1px dashed color-mix(in srgb, var(--primary) 45%, var(--line));
  border-radius: 16px;
  padding: 12px 14px;
  color: var(--muted);
  background: color-mix(in srgb, var(--solid-card) 85%, var(--primary-soft));
}

.ai-loading-box {
  display: flex;
  align-items: center;
  gap: 14px;
  border: 1px solid var(--line);
  border-radius: 20px;
  padding: 18px;
  background: var(--solid-card);
}

.ai-spinner {
  flex: 0 0 34px;
  width: 34px;
  height: 34px;
  border: 4px solid color-mix(in srgb, var(--primary) 18%, var(--line));
  border-top-color: var(--primary);
  border-radius: 999px;
  animation: aiSpin 0.8s linear infinite;
}

@keyframes aiSpin {
  to { transform: rotate(360deg); }
}

.ai-review-top-btn {
  border-color: color-mix(in srgb, #7c3aed 36%, var(--line)) !important;
  color: color-mix(in srgb, #7c3aed 70%, var(--text));
}

[data-theme="dark"] .ai-empty-icon {
  color: #ddd6fe;
  background: rgba(124, 58, 237, 0.22);
}

@media (max-width: 900px) {
  .ai-review-grid {
    grid-template-columns: 1fr;
  }

  .ai-review-main,
  .ai-loading-box {
    align-items: stretch;
    flex-direction: column;
  }

  .ai-badge {
    align-self: flex-start;
  }
}


/* Rubric image import for Teacher/Admin */
.rubric-image-import-card {
  display: grid;
  gap: 14px;
  border: 1px solid color-mix(in srgb, var(--primary) 32%, var(--line));
  border-radius: 22px;
  padding: 16px;
  background: linear-gradient(135deg, color-mix(in srgb, var(--solid-card) 86%, var(--primary-soft)), var(--solid-card));
  box-shadow: 0 16px 34px rgba(37, 99, 235, 0.08);
}

.rubric-import-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 14px;
}

.rubric-import-header h3 {
  margin-bottom: 4px;
}

.rubric-import-badge {
  flex: 0 0 auto;
  border-radius: 999px;
  padding: 7px 10px;
