  #adminOverlay .modal-header {
    position: sticky !important;
    top: 0 !important;
  }

  #studentAssistanceSettings {
    margin: 10px 10px 0 !important;
    padding: 12px !important;
    border-radius: 16px !important;
  }

  #adminOverlay .pin-screen,
