}

.entry-choice-icon {
  flex: 0 0 auto;
  display: grid;
  place-items: center;
  width: 50px;
  height: 50px;
  border-radius: 16px;
  background: rgba(255, 255, 255, 0.24);
  font-size: 1.6rem;
}

.guest-choice .entry-choice-icon,
