  inset: 0;
  z-index: 980000;
  display: grid;
  place-items: center;
  padding: 18px;
  background: rgba(2, 6, 23, 0.52);
  backdrop-filter: blur(8px);
}

.collab-members-overlay.hidden {
  display: none !important;
}

.collab-members-card {
  position: relative;
  width: min(560px, calc(100vw - 28px));
  max-height: calc(100dvh - 32px);
  overflow: auto;
  padding: 22px;
  border: 1px solid rgba(148, 163, 184, 0.28);
  border-radius: 26px;
  background: var(--solid-card, #ffffff);
  box-shadow: 0 34px 80px rgba(15, 23, 42, 0.34);
}

.collab-members-head {
  margin-right: 46px;
  margin-bottom: 14px;
}

.collab-members-head h2 {
  margin: 0;
  color: var(--text, #0f172a);
}

.collab-members-list {
  display: grid;
  gap: 10px;
}

.collab-member-row {
  display: grid;
  grid-template-columns: 42px 1fr auto;
  align-items: center;
  gap: 10px;
  padding: 10px;
  border: 1px solid var(--line, #dbeafe);
  border-radius: 18px;
  background: color-mix(in srgb, var(--solid-card) 88%, var(--primary-soft));
}

.collab-member-avatar {
  display: grid;
  place-items: center;
  width: 42px;
  height: 42px;
  border-radius: 14px;
  background: linear-gradient(135deg, #dbeafe, #ccfbf1);
}

.collab-member-main {
  display: grid;
  gap: 2px;
