/* =========================================================
   Step 164: Responsive PDF Lesson Viewer + Lesson Manager
   ========================================================= */
body.lesson-viewer-active,
body.lesson-pdf-open {
  overflow: hidden !important;
}

body.lesson-viewer-active > .app-shell,
body.lesson-viewer-active > .hidden-admin-trigger,
body.lesson-viewer-active > .student-dashboard-screen {
