}

.lesson-viewer-screen {
  position: fixed;
  inset: 0;
  z-index: 12500;
  overflow: auto;
  color: var(--text);
  background:
    radial-gradient(circle at 8% 4%, rgba(37, 99, 235, 0.18), transparent 28rem),
    radial-gradient(circle at 92% 28%, rgba(14, 165, 233, 0.13), transparent 24rem),
    linear-gradient(145deg, var(--bg), var(--bg-2));
