  align-items: center;
  gap: 10px;
}

.lesson-library-brand {
  min-width: 0;
}

.lesson-library-brand h1,
.lesson-pdf-heading h2,
.lesson-manager-heading h3,
.lesson-editor-card h4,
.lesson-admin-library-card h4 {
  margin: 0;
}

.lesson-library-brand .muted-text,
.lesson-pdf-heading .muted-text {
  margin: 2px 0 0;
}

.lesson-library-icon {
  display: grid;
  place-items: center;
  width: 52px;
  height: 52px;
  flex: 0 0 auto;
  border-radius: 17px;
  font-size: 25px;
  background: linear-gradient(145deg, rgba(37, 99, 235, 0.18), rgba(14, 165, 233, 0.08));
  border: 1px solid rgba(37, 99, 235, 0.22);
}

.lesson-library-back-btn {
  min-height: 42px;
}

.lesson-library-main {
  width: min(1320px, calc(100% - 36px));
  margin: 0 auto;
  padding: clamp(18px, 2.6vw, 34px) 0 56px;
}

.lesson-library-welcome-card {
  display: grid;
  grid-template-columns: 1fr auto;
  align-items: center;
  gap: 22px;
  padding: clamp(18px, 2.6vw, 30px);
  overflow: hidden;
  border: 1px solid rgba(37, 99, 235, 0.18);
  border-radius: 24px;
  background:
    linear-gradient(120deg, color-mix(in srgb, var(--card) 95%, transparent), color-mix(in srgb, var(--card-2) 86%, transparent)),
    var(--card);
  box-shadow: var(--shadow-soft);
}

.lesson-library-welcome-card h2 {
  margin: 6px 0;
  max-width: 720px;
  font-size: clamp(22px, 3vw, 34px);
  line-height: 1.12;
}

.lesson-library-welcome-card p {
  max-width: 780px;
  margin: 0;
  color: var(--muted);
  line-height: 1.5;
}

.lesson-library-eyebrow,
.lesson-pdf-term,
.lesson-card-term,
.lesson-editor-mode-badge,
.lesson-optional-label {
  display: inline-flex;
  align-items: center;
  width: fit-content;
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--primary);
}

.lesson-library-stat {
  display: grid;
  place-items: center;
  min-width: 104px;
  min-height: 86px;
  padding: 12px;
  border-radius: 20px;
  color: #fff;
  background: linear-gradient(145deg, #2563eb, #0ea5e9);
  box-shadow: 0 14px 30px rgba(37, 99, 235, 0.2);
}

.lesson-library-stat strong {
  font-size: 34px;
