.lesson-library-controls {
  margin-top: 22px;
  padding: 16px;
  border: 1px solid var(--line);
  border-radius: 22px;
  background: color-mix(in srgb, var(--card) 92%, transparent);
  box-shadow: var(--shadow-soft);
}

.lesson-term-tabs {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
}

.lesson-term-tab,
.lesson-file-source-tab {
  min-height: 46px;
  border: 1px solid var(--line);
  border-radius: 14px;
  color: var(--muted);
  background: var(--card-2);
  font: inherit;
  font-weight: 800;
  cursor: pointer;
  transition: 160ms ease;
}

.lesson-term-tab span {
  display: inline-grid;
  place-items: center;
  min-width: 24px;
  height: 24px;
  margin-left: 6px;
  border-radius: 999px;
  font-size: 12px;
  background: rgba(148, 163, 184, 0.16);
}

.lesson-term-tab:hover,
.lesson-file-source-tab:hover {
  border-color: rgba(37, 99, 235, 0.4);
  transform: translateY(-1px);
}

.lesson-term-tab.active,
.lesson-file-source-tab.active {
  color: #fff;
  border-color: transparent;
  background: linear-gradient(145deg, #2563eb, #0ea5e9);
  box-shadow: 0 10px 24px rgba(37, 99, 235, 0.2);
}

.lesson-term-tab.active span {
  background: rgba(255, 255, 255, 0.2);
}

.lesson-library-filter-row {
  margin-top: 12px;
}

.lesson-library-search {
  display: flex;
  align-items: center;
  flex: 1;
  gap: 9px;
  min-width: 0;
  padding: 0 14px;
  border: 1px solid var(--line);
  border-radius: 14px;
  background: var(--input-bg, var(--card));
}

.lesson-library-search input,
.lesson-library-filter-row select,
.lesson-admin-list-filters input,
.lesson-admin-list-filters select {
  min-height: 46px;
}

.lesson-library-search input {
  width: 100%;
  border: 0 !important;
  outline: 0;
  padding: 0 !important;
  background: transparent !important;
  box-shadow: none !important;
}

.lesson-library-filter-row select {
  width: min(230px, 34vw);
}

.lesson-library-status {
  min-height: 32px;
  padding: 14px 4px 4px;
  color: var(--muted);
  font-size: 13px;
  font-weight: 700;
}

.lesson-library-status[data-type="error"],
.lesson-admin-publish-row .helper-note[data-type="error"],
#lessonDriveStatus[data-type="error"] {
  color: #dc2626;
}

.lesson-library-status[data-type="success"],
.lesson-admin-publish-row .helper-note[data-type="success"],
#lessonDriveStatus[data-type="success"] {
  color: #15803d;
}

.lesson-library-status[data-type="warning"],
.lesson-admin-publish-row .helper-note[data-type="warning"],
#lessonDriveStatus[data-type="warning"] {
  color: #b45309;
}

.lesson-library-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(275px, 1fr));
  gap: 18px;
  margin-top: 10px;
}

.lesson-library-card {
  content-visibility: auto;
  contain: layout paint style;
  contain-intrinsic-size: 280px 238px;
  min-width: 0;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 24px;
  background: var(--card);
  box-shadow: var(--shadow-soft);
  transition: 180ms ease;
}

.lesson-library-card:hover {
  border-color: rgba(37, 99, 235, 0.36);
  box-shadow: var(--shadow);
  transform: translateY(-3px);
}

.lesson-card-open {
  display: grid;
  grid-template-columns: 94px minmax(0, 1fr);
  width: 100%;
  min-height: 238px;
  padding: 0;
  border: 0;
  color: inherit;
  background: transparent;
  text-align: left;
  cursor: pointer;
}

.lesson-card-cover {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 9px;
  overflow: hidden;
  color: #fff;
  background:
    linear-gradient(165deg, rgba(255,255,255,0.18), transparent 42%),
    linear-gradient(160deg, #2563eb, #0f4cb8 62%, #0ea5e9);
}

.lesson-card-cover::after {
  content: '';
  position: absolute;
  right: -28px;
  bottom: -28px;
  width: 88px;
  height: 88px;
  border-radius: 50%;
  background: rgba(255,255,255,0.12);
}

.lesson-card-number {
  font-size: 30px;
  font-weight: 900;
  line-height: 1;
}

.lesson-card-pdf {
  padding: 4px 8px;
  border-radius: 8px;
  font-size: 10px;
  font-weight: 900;
  letter-spacing: 0.12em;
  background: rgba(255, 255, 255, 0.18);
}

.lesson-card-book {
  font-size: 24px;
}

.lesson-card-content {
  display: flex;
  flex-direction: column;
  min-width: 0;
  padding: 20px;
}

.lesson-card-content h3 {
  display: -webkit-box;
  overflow: hidden;
  margin: 7px 0 8px;
  font-size: 18px;
  line-height: 1.3;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
}

.lesson-card-content p {
  display: -webkit-box;
  overflow: hidden;
  margin: 0;
  color: var(--muted);
  font-size: 13px;
  line-height: 1.55;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
}

.lesson-card-meta {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  margin-top: auto;
  padding-top: 16px;
  color: var(--muted);
  font-size: 11px;
  font-weight: 700;
}

.lesson-card-cta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 12px;
  color: var(--primary);
  font-size: 13px;
  font-weight: 900;
}

.lesson-library-empty {
  grid-column: 1 / -1;
  display: grid;
  place-items: center;
  min-height: 290px;
  padding: 36px;
  border: 1px dashed var(--line-strong);
  border-radius: 24px;
  background: var(--card);
  text-align: center;
}

.lesson-library-empty > span {
  font-size: 42px;
}

.lesson-library-empty h3 {
  margin: 12px 0 5px;
}

.lesson-library-empty p {
  margin: 0;
  color: var(--muted);
}

.lesson-pdf-overlay {
  content-visibility: auto;
  contain: layout paint style;
  position: fixed;
  inset: 0;
  z-index: 30000;
  display: grid;
  place-items: center;
  padding: 18px;
  background: rgba(2, 6, 23, 0.76);
  backdrop-filter: blur(12px);
}

.lesson-pdf-card {
  position: relative;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
  width: min(1500px, 100%);
  height: min(94vh, 980px);
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, 0.18);
  border-radius: 26px;
  background: var(--card);
  box-shadow: 0 30px 90px rgba(2, 6, 23, 0.42);
}

.lesson-pdf-card:fullscreen {
  width: 100vw;
  height: 100vh;
  border: 0;
  border-radius: 0;
}

.lesson-pdf-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  min-width: 0;
  padding: 14px 16px 14px 20px;
  border-bottom: 1px solid var(--line);
  background: var(--card);
}

.lesson-pdf-heading {
  display: flex;
  align-items: center;
  gap: 14px;
  min-width: 0;
}

.lesson-pdf-heading > div {
  min-width: 0;
}

.lesson-pdf-heading h2,
.lesson-pdf-heading p {
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.lesson-pdf-term {
  flex: 0 0 auto;
  padding: 7px 10px;
  border-radius: 999px;
  background: rgba(37, 99, 235, 0.12);
}

.lesson-link-btn {
  text-decoration: none;
}

.lesson-pdf-body {
  position: relative;
  min-height: 0;
  background: #d9dee7;
}

.lesson-pdf-frame {
  display: block;
  content-visibility: auto;
  width: 100%;
  height: 100%;
  border: 0;
  background: #fff;
}

.lesson-pdf-loading {
  position: absolute;
  inset: 0;
  z-index: 2;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 24px;
  color: #1e293b;
  background: linear-gradient(145deg, #f8fafc, #e2e8f0);
  text-align: center;
}

.lesson-pdf-loading small {
  color: #64748b;
}

.lesson-pdf-loading.lesson-pdf-load-warning {
  background: linear-gradient(145deg, #fff7ed, #ffedd5);
}


.lesson-pdf-wake-layer {
  display: none;
  position: absolute;
  inset: 0;
  z-index: 5;
  background: transparent;
}

@media (hover: hover) and (pointer: fine) {
  .lesson-pdf-card:fullscreen,
  .lesson-pdf-card.lesson-native-fullscreen {
    display: block;
    width: 100vw;
    height: 100vh;
    overflow: hidden;
    border: 0;
    border-radius: 0;
    background: #05070b;
    cursor: default;
  }

  .lesson-pdf-card:fullscreen .lesson-pdf-body,
  .lesson-pdf-card.lesson-native-fullscreen .lesson-pdf-body {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    min-height: 0;
    background: #05070b;
  }

  .lesson-pdf-card:fullscreen .lesson-pdf-frame,
  .lesson-pdf-card.lesson-native-fullscreen .lesson-pdf-frame {
    width: 100%;
    height: 100%;
    background: #05070b;
  }

  /* Floating controls: overlay only, so the PDF never resizes or jumps. */
  .lesson-pdf-card:fullscreen .lesson-pdf-header,
  .lesson-pdf-card.lesson-native-fullscreen .lesson-pdf-header {
    position: absolute;
    top: 14px;
    left: 50%;
    z-index: 12;
    width: min(920px, calc(100vw - 32px));
    min-height: 54px;
    padding: 8px 10px 8px 14px;
    border: 1px solid rgba(255, 255, 255, 0.18);
    border-radius: 18px;
    color: #fff;
    background: rgba(8, 12, 22, 0.82);
    box-shadow: 0 14px 42px rgba(0, 0, 0, 0.35);
    backdrop-filter: blur(18px) saturate(135%);
    -webkit-backdrop-filter: blur(18px) saturate(135%);
    transform: translate(-50%, 0);
    opacity: 1;
    pointer-events: auto;
    transition: transform 240ms ease, opacity 220ms ease;
  }

  .lesson-pdf-card:fullscreen .lesson-pdf-heading,
  .lesson-pdf-card.lesson-native-fullscreen .lesson-pdf-heading {
    flex: 1 1 auto;
    min-width: 0;
  }

  .lesson-pdf-card:fullscreen .lesson-pdf-heading h2,
  .lesson-pdf-card.lesson-native-fullscreen .lesson-pdf-heading h2 {
    margin: 0;
    color: #fff;
    font-size: 15px;
    line-height: 1.25;
    font-weight: 750;
  }

  .lesson-pdf-card:fullscreen .lesson-pdf-term,
  .lesson-pdf-card:fullscreen .lesson-pdf-heading .muted-text,
  .lesson-pdf-card:fullscreen #lessonPdfOpenBtn,
  .lesson-pdf-card:fullscreen #lessonPdfDownloadBtn,
  .lesson-pdf-card.lesson-native-fullscreen .lesson-pdf-term,
  .lesson-pdf-card.lesson-native-fullscreen .lesson-pdf-heading .muted-text,
  .lesson-pdf-card.lesson-native-fullscreen #lessonPdfOpenBtn,
  .lesson-pdf-card.lesson-native-fullscreen #lessonPdfDownloadBtn {
    display: none !important;
  }

  .lesson-pdf-card:fullscreen .lesson-pdf-actions,
  .lesson-pdf-card.lesson-native-fullscreen .lesson-pdf-actions {
    flex: 0 0 auto;
    gap: 7px;
  }

  .lesson-pdf-card:fullscreen .lesson-pdf-actions .ghost-btn,
  .lesson-pdf-card:fullscreen .lesson-pdf-actions .icon-btn,
  .lesson-pdf-card.lesson-native-fullscreen .lesson-pdf-actions .ghost-btn,
  .lesson-pdf-card.lesson-native-fullscreen .lesson-pdf-actions .icon-btn {
    min-height: 38px;
    color: #fff;
    border-color: rgba(255, 255, 255, 0.2);
    background: rgba(255, 255, 255, 0.09);
    box-shadow: none;
  }

  .lesson-pdf-card:fullscreen .lesson-pdf-actions .ghost-btn:hover,
  .lesson-pdf-card:fullscreen .lesson-pdf-actions .icon-btn:hover,
  .lesson-pdf-card.lesson-native-fullscreen .lesson-pdf-actions .ghost-btn:hover,
  .lesson-pdf-card.lesson-native-fullscreen .lesson-pdf-actions .icon-btn:hover {
    background: rgba(255, 255, 255, 0.18);
  }

  .lesson-pdf-card:fullscreen.lesson-controls-hidden,
  .lesson-pdf-card.lesson-native-fullscreen.lesson-controls-hidden {
    cursor: none;
  }

  .lesson-pdf-card:fullscreen.lesson-controls-hidden .lesson-pdf-header,
  .lesson-pdf-card.lesson-native-fullscreen.lesson-controls-hidden .lesson-pdf-header {
    transform: translate(-50%, -135%);
    opacity: 0;
    pointer-events: none;
  }

  /* This transparent layer only wakes the controls after idle. It disappears
     immediately on pointer movement so the PDF remains fully interactive. */
  .lesson-pdf-card:fullscreen.lesson-controls-hidden .lesson-pdf-wake-layer,
  .lesson-pdf-card.lesson-native-fullscreen.lesson-controls-hidden .lesson-pdf-wake-layer {
    display: block;
    cursor: none;
    pointer-events: auto;
  }
}

.lesson-loading-spinner {
  width: 34px;
  height: 34px;
  border: 4px solid rgba(37, 99, 235, 0.18);
  border-top-color: #2563eb;
  border-radius: 50%;
  animation: lesson-spin 0.8s linear infinite;
}

@keyframes lesson-spin { to { transform: rotate(360deg); } }

.dashboard-lessons-hero-btn,
.dashboard-lesson-viewer-btn {
  white-space: nowrap;
}

/* Teacher lesson manager */
.lesson-manager-admin {
  padding: 2px 0 12px;
}

.lesson-manager-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  margin-bottom: 16px;
}

.lesson-manager-heading p {
  margin-bottom: 0;
}

.lesson-drive-setup-notice {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 14px;
  padding: 16px;
  border: 1px solid rgba(245, 158, 11, 0.35);
  border-radius: 18px;
  background: rgba(245, 158, 11, 0.08);
}

.lesson-drive-setup-notice.drive-ready {
  border-color: rgba(37, 99, 235, 0.3);
  background: rgba(37, 99, 235, 0.07);
}

.lesson-drive-setup-notice.drive-connected {
  border-color: rgba(34, 197, 94, 0.35);
  background: rgba(34, 197, 94, 0.08);
}

.lesson-drive-setup-notice p {
  margin: 3px 0 0;
  color: var(--muted);
  font-size: 13px;
  line-height: 1.5;
}

.lesson-drive-notice-icon {
  display: grid;
  place-items: center;
  width: 44px;
  height: 44px;
  border-radius: 14px;
  font-size: 22px;
  background: var(--card);
  border: 1px solid var(--line);
}

.lesson-manager-layout {
  display: grid;
  grid-template-columns: minmax(320px, 0.88fr) minmax(440px, 1.35fr);
  align-items: start;
  gap: 16px;
  margin-top: 16px;
}

.lesson-editor-card,
.lesson-admin-library-card {
  min-width: 0;
  padding: 18px;
  border: 1px solid var(--line);
  border-radius: 20px;
  background: var(--card);
  box-shadow: var(--shadow-soft);
}

.lesson-editor-card {
  position: sticky;
  top: 0;
}

.lesson-editor-card-head {
  justify-content: space-between;
  margin-bottom: 14px;
}

.lesson-editor-mode-badge {
  padding: 5px 8px;
  border-radius: 999px;
  background: rgba(37, 99, 235, 0.1);
}

.lesson-admin-form-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(110px, 0.4fr);
  gap: 12px;
}

.lesson-admin-form-grid label:first-child {
  grid-column: 1 / -1;
}

.lesson-file-source-tabs {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
  margin: 14px 0 10px;
}

.lesson-file-source-tab {
  min-height: 42px;
  font-size: 13px;
}

.lesson-file-dropzone {
  display: grid !important;
  place-items: center;
  min-height: 155px;
  padding: 20px !important;
  border: 2px dashed var(--line-strong) !important;
  border-radius: 18px;
  background: var(--card-2);
  text-align: center;
  cursor: pointer;
  transition: 160ms ease;
}

.lesson-file-dropzone:hover {
  border-color: #2563eb !important;
  background: rgba(37, 99, 235, 0.06);
}

.lesson-file-dropzone input {
  position: absolute;
  width: 1px;
  height: 1px;
  opacity: 0;
  pointer-events: none;
}

.lesson-file-drop-icon {
  font-size: 34px;
}

.lesson-file-dropzone strong {
  max-width: 100%;
  margin-top: 6px;
  overflow-wrap: anywhere;
}

.lesson-file-dropzone small {
  margin-top: 4px;
  color: var(--muted);
}

.lesson-admin-publish-row {
  align-items: flex-start;
  margin-top: 16px;
}

.lesson-admin-publish-row .helper-note {
  flex: 1;
  margin: 8px 0 0;
}

.lesson-admin-list-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 10px;
}

.lesson-admin-list-head p {
  margin: 3px 0 0;
}

.lesson-admin-list-filters {
  flex-wrap: wrap;
  justify-content: flex-end;
}

.lesson-admin-list-filters input {
  width: min(220px, 100%);
}

.lesson-admin-list {
  display: grid;
  gap: 10px;
  margin-top: 10px;
}

.lesson-admin-row {
  display: grid;
  grid-template-columns: 48px minmax(0, 1fr) auto;
  align-items: center;
  gap: 12px;
  padding: 12px;
  border: 1px solid var(--line);
  border-radius: 16px;
  background: var(--card-2);
}

.lesson-admin-order {
  display: grid;
  place-items: center;
  width: 44px;
  height: 44px;
  border-radius: 14px;
  color: #fff;
  font-size: 18px;
  font-weight: 900;
  background: linear-gradient(145deg, #2563eb, #0ea5e9);
}

.lesson-admin-row-main {
  min-width: 0;
}

.lesson-admin-row-title {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.lesson-admin-row-title span {
  flex: 0 0 auto;
  padding: 4px 7px;
  border-radius: 999px;
  color: var(--primary);
  font-size: 10px;
  font-weight: 900;
  background: rgba(37, 99, 235, 0.1);
}

.lesson-admin-row-title strong {
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.lesson-admin-row-main p,
.lesson-admin-row-main small {
  overflow: hidden;
  margin: 4px 0 0;
  color: var(--muted);
  white-space: nowrap;
  text-overflow: ellipsis;
}

.lesson-admin-row-actions {
  display: flex;
  align-items: center;
  gap: 5px;
  flex-wrap: wrap;
  justify-content: flex-end;
}

.lesson-admin-row-actions .ghost-btn {
  min-height: 36px;
  padding: 7px 9px;
  font-size: 12px;
}

.lesson-admin-empty {
  display: grid;
  place-items: center;
  min-height: 220px;
  border: 1px dashed var(--line-strong);
  border-radius: 16px;
  color: var(--muted);
  text-align: center;
}

.lesson-admin-empty span {
  font-size: 34px;
}

.lesson-admin-empty p {
  margin: 4px 0 0;
}

[data-theme="dark"] .lesson-library-status[data-type="success"],
[data-theme="dark"] .lesson-admin-publish-row .helper-note[data-type="success"],
[data-theme="dark"] #lessonDriveStatus[data-type="success"] { color: #86efac; }
[data-theme="dark"] .lesson-library-status[data-type="warning"],
[data-theme="dark"] .lesson-admin-publish-row .helper-note[data-type="warning"],
[data-theme="dark"] #lessonDriveStatus[data-type="warning"] { color: #fdba74; }
[data-theme="dark"] .lesson-library-status[data-type="error"],
[data-theme="dark"] .lesson-admin-publish-row .helper-note[data-type="error"],
[data-theme="dark"] #lessonDriveStatus[data-type="error"] { color: #fca5a5; }

@media (max-width: 980px) {
  .lesson-manager-layout {
    grid-template-columns: 1fr;
  }
  .lesson-editor-card {
    position: static;
  }
  .lesson-admin-row {
    grid-template-columns: 48px minmax(0, 1fr);
  }
  .lesson-admin-row-actions {
    grid-column: 1 / -1;
    justify-content: flex-start;
    padding-left: 60px;
  }
}

