  .lesson-library-brand {
    gap: 8px;
  }
  .lesson-library-icon,
  .lesson-library-brand .muted-text,
  .lesson-library-header-actions #lessonLibraryRefreshBtn {
    display: none;
  }
  .lesson-library-brand .section-kicker {
    font-size: 9px;
  }
  .lesson-library-brand h1 {
    font-size: 19px;
  }
  .lesson-library-back-btn,
  .lesson-library-header-actions .ghost-btn {
    min-height: 38px;
    padding: 8px 10px;
    font-size: 12px;
  }
  .lesson-library-main {
    width: min(100% - 20px, 680px);
    padding: 12px 0 max(28px, env(safe-area-inset-bottom));
  }
  .lesson-library-welcome-card {
    grid-template-columns: 1fr auto;
