/* Step 169A: local reading progress + continue reading */
.lesson-continue-card {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 16px;
  margin-top: 18px;
  padding: 16px;
  border: 1px solid rgba(37, 99, 235, 0.22);
  border-radius: 22px;
  background:
    linear-gradient(120deg, color-mix(in srgb, var(--card) 94%, transparent), color-mix(in srgb, var(--card-2) 88%, transparent)),
    var(--card);
  box-shadow: var(--shadow-soft);
}

.lesson-continue-icon {
  display: grid;
  place-items: center;
  width: 52px;
  height: 52px;
  border-radius: 18px;
  background: linear-gradient(145deg, rgba(37, 99, 235, 0.17), rgba(14, 165, 233, 0.09));
  border: 1px solid rgba(37, 99, 235, 0.18);
  font-size: 24px;
}

.lesson-continue-content {
  min-width: 0;
}

.lesson-continue-content h3 {
  overflow: hidden;
  margin: 5px 0 3px;
  white-space: nowrap;
  text-overflow: ellipsis;
  font-size: 18px;
}

.lesson-continue-content p {
  margin: 0 0 10px;
  font-size: 13px;
}

.lesson-progress-track {
  width: 100%;
  height: 8px;
  overflow: hidden;
  border-radius: 999px;
  background: rgba(148, 163, 184, 0.2);
}

.lesson-progress-track span {
  display: block;
  height: 100%;
  width: 0;
  border-radius: inherit;
  background: linear-gradient(90deg, #2563eb, #0ea5e9);
  transition: width 220ms ease;
}

.lesson-card-progress {
  display: grid;
  gap: 7px;
  margin-top: 14px;
  padding: 10px;
  border: 1px solid rgba(148, 163, 184, 0.18);
  border-radius: 14px;
  background: color-mix(in srgb, var(--card-2) 82%, transparent);
}

.lesson-card-progress > span {
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
  color: var(--muted);
  font-size: 11px;
  font-weight: 850;
}

.lesson-card-progress[data-status="completed"] {
  border-color: rgba(22, 163, 74, 0.22);
  background: rgba(22, 163, 74, 0.08);
}

.lesson-card-progress[data-status="completed"] .lesson-progress-track span {
  background: linear-gradient(90deg, #16a34a, #22c55e);
}

.lesson-card-progress[data-status="completed"] > span {
  color: #15803d;
}

.lesson-card-progress[data-status="in-progress"] {
  border-color: rgba(37, 99, 235, 0.24);
  background: rgba(37, 99, 235, 0.07);
}

.lesson-pdf-progress-text {
  margin: 4px 0 0;
  color: var(--muted);
  font-size: 12px;
  font-weight: 800;
}

.lesson-pdf-progress-text[data-status="completed"] {
  color: #15803d;
}

.lesson-pdf-progress-text[data-status="in-progress"] {
  color: var(--primary);
}

.lesson-mark-done-btn:disabled {
  opacity: 0.7;
  cursor: default;
}

@media (hover: hover) and (pointer: fine) {
  .lesson-pdf-card:fullscreen .lesson-pdf-progress-text,
  .lesson-pdf-card:fullscreen #lessonPdfMarkDoneBtn,
  .lesson-pdf-card.lesson-native-fullscreen .lesson-pdf-progress-text,
  .lesson-pdf-card.lesson-native-fullscreen #lessonPdfMarkDoneBtn {
    display: none !important;
  }
}

@media (max-width: 720px) {
  .lesson-continue-card {
    grid-template-columns: auto minmax(0, 1fr);
    align-items: start;
  }

  .lesson-continue-card .primary-btn {
    grid-column: 1 / -1;
    width: 100%;
  }

  .lesson-continue-content h3 {
    white-space: normal;
    display: -webkit-box;
    -webkit-line-clamp: 2;
    -webkit-box-orient: vertical;
  }

  .lesson-card-progress {
    padding: 9px;
  }

  .lesson-pdf-progress-text {
    white-space: normal !important;
  }
}

