/* =========================================================
   STEP 194 - ICT 8 CONNECT BRANDING
   Rebrands the app without touching feature logic. The brand line always stays
   on one line and cycles softly between the app name and tagline.
   ========================================================= */
.brand-cycle {
  --ict8-cycle-duration: 5.8s;
  position: relative !important;
  display: inline-grid !important;
  grid-template-areas: "brand" !important;
  align-items: center !important;
  justify-items: start !important;
  width: max-content !important;
  max-width: 100% !important;
  min-width: min(18ch, 100%) !important;
  white-space: nowrap !important;
  line-height: 1 !important;
  vertical-align: middle !important;
  overflow: hidden !important;
}

.brand-cycle-face {
  grid-area: brand !important;
  display: inline-block !important;
  white-space: nowrap !important;
  will-change: opacity, transform, filter !important;
  animation-duration: var(--ict8-cycle-duration) !important;
  animation-timing-function: cubic-bezier(.4, 0, .2, 1) !important;
  animation-iteration-count: infinite !important;
}

.brand-cycle-name {
  animation-name: ict8BrandNameCycle !important;
}

.brand-cycle-tagline {
  animation-name: ict8BrandTaglineCycle !important;
}

@keyframes ict8BrandNameCycle {
  0%, 39%, 100% { opacity: 1; transform: translateY(0) scale(1); filter: blur(0); }
  47%, 91% { opacity: 0; transform: translateY(-0.36em) scale(.985); filter: blur(3px); }
}

@keyframes ict8BrandTaglineCycle {
  0%, 43%, 96%, 100% { opacity: 0; transform: translateY(0.36em) scale(.985); filter: blur(3px); }
  51%, 87% { opacity: 1; transform: translateY(0) scale(1); filter: blur(0); }
