  caret-color: var(--editor-text) !important;
  overflow-y: auto !important;
  overflow-x: auto !important;
  user-select: text !important;
  -webkit-user-select: text !important;
  text-rendering: optimizeLegibility;
}

#codeEditor::selection {
  color: var(--editor-text) !important;
  -webkit-text-fill-color: var(--editor-text) !important;
  background: rgba(96, 165, 250, 0.35) !important;
}

.code-match-layer {
  display: none !important;
  visibility: hidden !important;
  pointer-events: none !important;
}

.editor-stack {
  isolation: auto !important;
}

body.result-checking #resultBtn,
body.result-checking #stepResultBtn,
body.result-checking #fullscreenResultBtn {
  pointer-events: auto !important;
}


/* =========================================================
   v252 Cursor-safe syntax highlighting restore
   - Restores Notepad++/VS Code-like colors for HTML, CSS, and JavaScript.
   - Keeps the textarea as the real typing/caret/copy source.
   - The visual layer is pointer-events:none and its geometry is synced by JS.
   ========================================================= */
.editor-stack {
  position: relative !important;
  isolation: isolate !important;
}

#codeEditor,
.code-match-layer {
  box-sizing: border-box !important;
  width: 100% !important;
  padding: 18px !important;
  font: var(--editor-font-size, 15px)/1.65 Consolas, Monaco, "Courier New", monospace !important;
  letter-spacing: 0 !important;
  tab-size: 2 !important;
  white-space: pre-wrap !important;
  overflow-wrap: break-word !important;
  word-break: normal !important;
}

#codeEditor {
  position: relative !important;
  z-index: 2 !important;
  display: block !important;
  color: transparent !important;
  -webkit-text-fill-color: transparent !important;
  caret-color: var(--editor-text) !important;
  background: transparent !important;
  border: 0 !important;
  outline: none !important;
  resize: none !important;
  text-rendering: optimizeLegibility !important;
}

#codeEditor::selection {
  color: transparent !important;
  -webkit-text-fill-color: transparent !important;
  background: rgba(96, 165, 250, 0.35) !important;
}

.code-match-layer {
  display: block !important;
  visibility: visible !important;
  position: absolute !important;
  inset: 0 auto auto 0 !important;
  z-index: 1 !important;
  color: var(--editor-text) !important;
  background: transparent !important;
  pointer-events: none !important;
  user-select: none !important;
  overflow: hidden !important;
  scrollbar-width: none !important;
}

.code-match-layer::-webkit-scrollbar {
  display: none !important;
}

.code-match-layer .tag-match {
  color: inherit !important;
  border-radius: 4px !important;
  text-decoration-line: underline !important;
  text-decoration-thickness: 3px !important;
  text-underline-offset: 4px !important;
}

.code-match-layer .tag-match-pair {
  background: rgba(37, 99, 235, 0.16) !important;
  text-decoration-color: #2563eb !important;
}

.code-match-layer .tag-match-missing {
  background: rgba(239, 68, 68, 0.16) !important;
  text-decoration-color: #ef4444 !important;
  text-decoration-style: wavy !important;
}

.code-match-layer .tag-match-self {
  background: rgba(22, 163, 74, 0.15) !important;
  text-decoration-color: #16a34a !important;
}

@media (min-width: 821px) {
  .editor-panel #codeEditor,
  .editor-panel .code-match-layer {
    white-space: pre-wrap !important;
    overflow-wrap: break-word !important;
    word-break: normal !important;
  }
}

/* Step 253: Student/activity labels inside Result & Feedback for easier recording */
.result-record-header {
