/* Step 258: keep long admin Login Check dialogs readable and closable on every screen. */
.app-dialog-overlay:not(.hidden) {
  overflow: auto;
  -webkit-overflow-scrolling: touch;
  align-items: flex-start;
  justify-content: center;
}

.app-dialog-overlay.long-dialog {
  padding-block: max(14px, env(safe-area-inset-top)) max(14px, env(safe-area-inset-bottom));
}

.app-dialog-card {
  position: relative;
}

.app-dialog-card.long-message {
  width: min(720px, calc(100vw - 24px));
  max-height: calc(100dvh - 28px);
  overflow: hidden;
  grid-template-rows: auto minmax(0, 1fr) auto;
  margin-block: auto;
}

.app-dialog-card.long-message .app-dialog-content {
  min-height: 0;
  max-height: calc(100dvh - 150px);
  overflow: auto;
  overscroll-behavior: contain;
  -webkit-overflow-scrolling: touch;
  padding-right: 0.35rem;
}

.app-dialog-card.long-message #appDialogMessage,
.app-dialog-card.long-message .app-dialog-content p:last-child {
  white-space: pre-wrap !important;
  overflow-wrap: anywhere;
  word-break: break-word;
  user-select: text;
  margin-bottom: 0.75rem;
}

.app-dialog-card.long-message .app-dialog-actions {
  position: sticky;
  bottom: 0;
  z-index: 2;
  margin: 0 -1.2rem -1.2rem;
  padding: 0.75rem 1.2rem 1.2rem;
  border-top: 1px solid var(--line);
  background: linear-gradient(180deg, color-mix(in srgb, var(--solid-card) 82%, transparent), var(--solid-card));
}

.app-dialog-close-btn {
  position: absolute;
  top: 0.65rem;
  right: 0.65rem;
  z-index: 5;
  width: 36px;
  height: 36px;
  border-radius: 999px;
  border: 1px solid var(--line-strong);
  background: var(--solid-card);
  color: var(--text);
  font-size: 1.25rem;
  font-weight: 900;
  line-height: 1;
  display: grid;
  place-items: center;
  cursor: pointer;
  box-shadow: var(--shadow-soft);
}

.app-dialog-close-btn:hover,
.app-dialog-close-btn:focus-visible {
  border-color: var(--primary);
  color: var(--primary);
  outline: none;
}

@media (max-width: 560px) {
  .app-dialog-overlay:not(.hidden) {
    align-items: flex-start;
  }

  .app-dialog-card.long-message {
    width: calc(100vw - 20px) !important;
    max-width: calc(100vw - 20px) !important;
    max-height: calc(100dvh - 20px) !important;
    border-radius: 22px !important;
  }

  .app-dialog-card.long-message .app-dialog-content {
    max-height: calc(100dvh - 170px);
  }

  .app-dialog-close-btn {
    top: 0.5rem;
    right: 0.5rem;
    width: 38px;
    height: 38px;
  }
}

