  -webkit-backdrop-filter: blur(8px);
  overflow: auto;
  opacity: 0;
  transition: opacity .22s ease;
}
.login-lacking-reminder-overlay.hidden { display: none !important; }
.login-lacking-reminder-overlay.is-visible { opacity: 1; }
.login-lacking-reminder-panel {
  position: relative;
  width: min(680px, 100%);
  max-height: min(780px, calc(100dvh - 36px));
  overflow: auto;
  overscroll-behavior: contain;
  border-radius: 24px;
  padding: 24px;
  background: #ffffff;
  color: #172033;
  border: 1px solid rgba(255,255,255,.7);
  box-shadow: 0 28px 80px rgba(15, 23, 42, .32);
