  opacity: 0;
  transition: transform .26s cubic-bezier(.22,.9,.25,1), opacity .22s ease;
}
.login-lacking-reminder-overlay.is-visible .login-lacking-reminder-panel {
  transform: translateY(0) scale(1);
  opacity: 1;
}
.login-lacking-reminder-overlay[data-state="missing"] .login-lacking-reminder-panel { border-top: 5px solid #f59e0b; }
.login-lacking-reminder-overlay[data-state="complete"] .login-lacking-reminder-panel { border-top: 5px solid #22c55e; }
.login-lacking-reminder-overlay[data-state="unavailable"] .login-lacking-reminder-panel { border-top: 5px solid #64748b; }
.login-lacking-reminder-close {
