/* Additional theme motion. */
@keyframes reminderThemeTwinkle { 0%,100% { opacity:.32; background-position:0 0,12px 7px,0 0; } 50% { opacity:.52; background-position:14px 18px,24px 2px,0 0; } }
@keyframes reminderThemeGridMove { from { background-position:0 0,0 0,0 0; } to { background-position:24px 24px,24px 24px,0 0; } }
@keyframes reminderThemeBubbleRise { from { background-position:0 54px,12px 82px,18px 72px,0 0; } to { background-position:0 -18px,12px -28px,18px -22px,0 0; } }
@keyframes reminderThemePetalDrift { from { background-position:0 0,12px 8px; } to { background-position:34px 76px,-18px 58px; } }
@keyframes reminderThemeArcadeShift { from { background-position:0 0,0 0; } to { background-position:16px 16px,16px 16px; } }
@keyframes reminderThemeConfetti { from { background-position:0 0,12px 8px,7px 18px; } to { background-position:18px 68px,-14px 60px,24px 72px; } }
@keyframes reminderThemeBunting { from { background-position:0 0,26px 0; } to { background-position:52px 0,78px 0; } }
@keyframes reminderThemeLeaves { from { background-position:0 0,18px 12px; } to { background-position:28px 52px,-12px 40px; } }

