.login-lacking-reminder-overlay[data-animation="subtle"][data-theme="cyber-neon"] .login-lacking-reminder-panel::before { animation:reminderThemeGridMove 10s linear infinite; }
.login-lacking-reminder-overlay[data-animation="normal"][data-theme="cyber-neon"] .login-lacking-reminder-panel::before { animation:reminderThemeGridMove 5s linear infinite; }
.login-lacking-reminder-overlay[data-animation="subtle"][data-theme="ocean"] .login-lacking-reminder-panel::before { animation:reminderThemeBubbleRise 13s linear infinite; }
.login-lacking-reminder-overlay[data-animation="normal"][data-theme="ocean"] .login-lacking-reminder-panel::before { animation:reminderThemeBubbleRise 7s linear infinite; }
