@keyframes reminderStyleMaxShift { 0%,100%{background-position:0 0,19px 13px,0 0} 50%{background-position:18px 26px,4px 34px,32px 20px} }
@keyframes reminderStyleGridScan { from{background-position:0 0,0 0,0 0} to{background-position:22px 22px,22px 22px,70px 70px} }
@keyframes reminderStyleVectorFloat { 0%,100%{background-position:0 0} 50%{background-position:18px 10px} }
@keyframes reminderStylePaperDrift { from{background-position:0 0,0 0} to{background-position:22px 10px,40px 0} }
@keyframes reminderStyleRetroWave { from{background-position:0 0,0 0} to{background-position:30px 18px,36px 20px} }
@keyframes reminderStyleCyberGlitch { 0%,92%,100%{background-position:0 0,0 0,0 0} 94%{background-position:7px 0,-5px 0,0 2px} 96%{background-position:-4px 0,6px 0,0 -2px} }
@keyframes reminderStyleDotsMove { from{background-position:0 0} to{background-position:14px 14px} }
