@keyframes reminderStyleClayFloat { 0%,100%{background-position:0 0} 50%{background-position:10px 14px} }
@keyframes reminderStylePixelStep { from{background-position:0 0,8px 8px} to{background-position:16px 16px,24px 24px} }
@keyframes reminderStyleEditorialSlide { from{background-position:0 0} to{background-position:25% 0} }
@keyframes reminderStyleY2KBubble { 0%,100%{background-position:0 0} 50%{background-position:10px -14px} }
@keyframes reminderStyleSwissSlide { from{background-position:0 0,0 0} to{background-position:18px 0,0 0} }
@keyframes reminderStyleSurrealFloat { 0%,100%{background-position:0 0} 50%{background-position:18px 12px} }
@keyframes reminderStyleBohoDrift { from{background-position:0 0} to{background-position:54px 54px} }
@keyframes reminderStyleVictorianShimmer { from{background-position:0 0,0 0} to{background-position:40px 0,92px 0} }
@keyframes reminderStyleGraffitiJitter { 0%,90%,100%{background-position:0 0,0 0,0 0,0 0} 93%{background-position:4px -2px,2px 1px,0 0,0 0} 96%{background-position:-3px 2px,-2px 0,0 0,0 0} }
@keyframes reminderStyleAuroraFlow { 0%,100%{background-position:0 0} 50%{background-position:18px -12px} }
