.login-lacking-reminder-overlay:is(
  [data-theme="minimalism"], [data-theme="maximalism"], [data-theme="futuristic"],
  [data-theme="vector-art"], [data-theme="collage-art"], [data-theme="retro"],
  [data-theme="cyberpunk"], [data-theme="pop-art"], [data-theme="glassmorphism"],
  [data-theme="clay-style"], [data-theme="pixel-art"], [data-theme="editorial"],
  [data-theme="y2k"], [data-theme="swiss-design"], [data-theme="surreal-design"],
  [data-theme="bohemian"], [data-theme="victorian-style"], [data-theme="graffiti"],
  [data-theme="aurora"], [data-theme="handwritten"]
)[data-animation="subtle"] .login-lacking-reminder-panel::before {
  animation-name:var(--ds-motion); animation-duration:14s; animation-timing-function:ease-in-out; animation-iteration-count:infinite;
}
.login-lacking-reminder-overlay:is(
  [data-theme="minimalism"], [data-theme="maximalism"], [data-theme="futuristic"],
  [data-theme="vector-art"], [data-theme="collage-art"], [data-theme="retro"],
  [data-theme="cyberpunk"], [data-theme="pop-art"], [data-theme="glassmorphism"],
  [data-theme="clay-style"], [data-theme="pixel-art"], [data-theme="editorial"],
  [data-theme="y2k"], [data-theme="swiss-design"], [data-theme="surreal-design"],
  [data-theme="bohemian"], [data-theme="victorian-style"], [data-theme="graffiti"],
  [data-theme="aurora"], [data-theme="handwritten"]
)[data-animation="normal"] .login-lacking-reminder-panel::before {
  animation-name:var(--ds-motion); animation-duration:7s; animation-timing-function:ease-in-out; animation-iteration-count:infinite;
}
.login-lacking-reminder-overlay[data-theme="pixel-art"][data-animation]:not([data-animation="off"]) .login-lacking-reminder-panel::before { animation-timing-function:steps(4,end); }
.login-lacking-reminder-overlay[data-theme="cyberpunk"][data-animation]:not([data-animation="off"]) .login-lacking-reminder-panel::before,
.login-lacking-reminder-overlay[data-theme="graffiti"][data-animation]:not([data-animation="off"]) .login-lacking-reminder-panel::before { animation-timing-function:steps(2,end); }

@media (max-height:620px) {
  .login-lacking-reminder-overlay:is(
    [data-theme="minimalism"], [data-theme="maximalism"], [data-theme="futuristic"], [data-theme="vector-art"],
    [data-theme="collage-art"], [data-theme="retro"], [data-theme="cyberpunk"], [data-theme="pop-art"],
    [data-theme="glassmorphism"], [data-theme="clay-style"], [data-theme="pixel-art"], [data-theme="editorial"],
    [data-theme="y2k"], [data-theme="swiss-design"], [data-theme="surreal-design"], [data-theme="bohemian"],
    [data-theme="victorian-style"], [data-theme="graffiti"], [data-theme="aurora"], [data-theme="handwritten"]
  ) .login-lacking-reminder-panel::after { font-size:3.5rem; padding:10px 14px; }
}

@media (prefers-reduced-motion:reduce) {
  .login-lacking-reminder-overlay .login-lacking-reminder-panel::before,
  .login-lacking-reminder-overlay .login-lacking-reminder-panel::after { animation:none !important; }
}


/* v294 — Automatic Academic Term Schedule */
.academic-term-schedule-card {
  border: 1px solid rgba(37, 99, 235, 0.22);
  border-radius: 20px;
  padding: 16px;
  background: linear-gradient(135deg, rgba(239, 246, 255, 0.92), rgba(248, 250, 252, 0.96));
  display: grid;
  gap: 14px;
}

.academic-term-schedule-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
}

.academic-term-schedule-head h4 {
  margin: 2px 0 0;
  font-size: 1.08rem;
}

.academic-term-schedule-head .muted-text {
  margin: 5px 0 0;
}

.academic-term-current-pill {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 34px;
  padding: 7px 11px;
  border-radius: 999px;
  background: rgba(37, 99, 235, 0.12);
  color: #1d4ed8;
  font-size: 0.78rem;
  font-weight: 900;
  letter-spacing: 0.04em;
  white-space: nowrap;
}

.academic-term-current-pill[data-mode="manual"] {
  background: rgba(245, 158, 11, 0.16);
  color: #92400e;
}

.academic-term-mode-grid,
.academic-term-date-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.academic-term-date-grid {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.academic-term-mode-grid label,
.academic-term-date-grid label {
  display: grid;
  gap: 6px;
  min-width: 0;
  font-weight: 800;
}

.academic-term-mode-grid select,
.academic-term-date-grid input {
  width: 100%;
  min-width: 0;
  border: 1px solid rgba(148, 163, 184, 0.45);
  border-radius: 13px;
  padding: 10px 11px;
  background: var(--input-bg, #fff);
  color: var(--text, #0f172a);
  font: inherit;
}

.academic-term-date-grid input {
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.04em;
}

.academic-term-date-grid small,
.compliance-admin-grid label > small {
  color: var(--muted, #64748b);
  font-weight: 650;
  line-height: 1.3;
}

.academic-term-schedule-summary {
  margin: 0;
  border-radius: 12px;
  padding: 10px 12px;
  background: rgba(255, 255, 255, 0.72);
}

@media (max-width: 820px) {
  .academic-term-schedule-head {
    align-items: stretch;
    flex-direction: column;
  }

  .academic-term-current-pill {
    width: fit-content;
  }

  .academic-term-date-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 560px) {
  .academic-term-schedule-card {
    padding: 13px;
    border-radius: 16px;
  }

  .academic-term-mode-grid {
    grid-template-columns: 1fr;
  }
}

/* v294.1 — Automatic Academic Term: dark-mode contrast hotfix */
[data-theme="dark"] .academic-term-schedule-card {
  color: #e5edf7 !important;
  border-color: rgba(96, 165, 250, 0.32) !important;
  background:
    radial-gradient(circle at top right, rgba(37, 99, 235, 0.16), transparent 24rem),
    linear-gradient(135deg, rgba(15, 23, 42, 0.98), rgba(17, 24, 39, 0.98)) !important;
  box-shadow: 0 14px 34px rgba(2, 6, 23, 0.28);
}

[data-theme="dark"] .academic-term-schedule-card .section-kicker {
  color: #7dd3fc !important;
}

[data-theme="dark"] .academic-term-schedule-head h4,
[data-theme="dark"] .academic-term-mode-grid label,
[data-theme="dark"] .academic-term-date-grid label {
  color: #f8fafc !important;
}

[data-theme="dark"] .academic-term-schedule-head .muted-text,
[data-theme="dark"] .academic-term-schedule-card .helper-note,
[data-theme="dark"] .academic-term-date-grid small {
  color: #cbd5e1 !important;
}

[data-theme="dark"] .academic-term-current-pill {
  color: #dbeafe !important;
  border: 1px solid rgba(96, 165, 250, 0.34);
  background: rgba(37, 99, 235, 0.24) !important;
  box-shadow: inset 0 0 0 1px rgba(147, 197, 253, 0.06);
}

[data-theme="dark"] .academic-term-current-pill[data-mode="manual"] {
  color: #fde68a !important;
  border-color: rgba(251, 191, 36, 0.32);
  background: rgba(245, 158, 11, 0.18) !important;
}

[data-theme="dark"] .academic-term-mode-grid select,
[data-theme="dark"] .academic-term-date-grid input {
  color: #f8fafc !important;
  border-color: rgba(96, 165, 250, 0.28) !important;
  background: rgba(2, 6, 23, 0.72) !important;
  color-scheme: dark;
}

[data-theme="dark"] .academic-term-mode-grid select:focus,
[data-theme="dark"] .academic-term-date-grid input:focus {
  color: #ffffff !important;
  border-color: #60a5fa !important;
  background: rgba(2, 6, 23, 0.94) !important;
  outline: none;
  box-shadow: 0 0 0 3px rgba(96, 165, 250, 0.16);
}

[data-theme="dark"] .academic-term-mode-grid select:disabled,
[data-theme="dark"] .academic-term-date-grid input:disabled {
  color: #aebed3 !important;
  -webkit-text-fill-color: #aebed3 !important;
  border-color: rgba(148, 163, 184, 0.20) !important;
  background: rgba(30, 41, 59, 0.78) !important;
  opacity: 1 !important;
}

[data-theme="dark"] .academic-term-mode-grid select option {
  color: #f8fafc;
  background: #0f172a;
}

[data-theme="dark"] .academic-term-schedule-summary {
  color: #dbeafe !important;
  border: 1px solid rgba(96, 165, 250, 0.18);
  background: rgba(30, 41, 59, 0.72) !important;
}

[data-theme="dark"] .academic-term-schedule-card .helper-note strong {
  color: #f8fafc !important;
}

/* =========================================================
   v295 — Teacher Needs Attention + Activities Given + Device QA
   ========================================================= */

/* ---------- Student Activities Given library ---------- */
.given-activities-screen {
  position: fixed;
  inset: 0;
  z-index: 1180;
  display: flex;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
  overflow: hidden;
  color: var(--text);
  background:
    radial-gradient(circle at 10% 0%, color-mix(in srgb, var(--primary) 16%, transparent), transparent 30rem),
    radial-gradient(circle at 95% 90%, color-mix(in srgb, var(--success) 12%, transparent), transparent 28rem),
    var(--bg);
}

.given-activities-header {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  padding: 18px clamp(16px, 3vw, 34px);
  border-bottom: 1px solid var(--line);
  background: color-mix(in srgb, var(--solid-card) 94%, transparent);
  backdrop-filter: blur(16px);
}

.given-activities-brand,
.given-activities-header-actions,
.given-activities-filter-row,
.given-activity-card-top,
.given-activity-card-meta,
.given-activity-viewer-header,
.given-activity-viewer-actions,
.given-activities-admin-heading,
.given-activities-admin-head-actions,
.given-activity-editor-head,
.given-activity-publish-row,
.given-activity-admin-list-head,
.given-activity-admin-title-line,
.given-activity-admin-actions,
.needs-attention-heading,
.needs-attention-student,
.needs-attention-meta,
.needs-attention-actions,
.device-qa-heading,
.device-qa-status-row {
  display: flex;
  align-items: center;
}

.given-activities-brand {
  gap: 14px;
  min-width: 0;
}

.given-activities-brand > div:last-child {
  min-width: 0;
}

.given-activities-brand h1 {
  margin: 0;
  font-size: clamp(1.45rem, 3vw, 2.15rem);
}

.given-activities-brand .muted-text {
  margin-top: 4px;
}

.given-activities-icon {
  display: grid;
  place-items: center;
  flex: 0 0 52px;
  width: 52px;
  height: 52px;
  border-radius: 18px;
  background: linear-gradient(135deg, var(--primary-soft), color-mix(in srgb, var(--success-soft) 82%, white));
  border: 1px solid var(--line-strong);
  font-size: 1.55rem;
}

.given-activities-header-actions {
  justify-content: flex-end;
  gap: 9px;
  flex-wrap: wrap;
}

.given-activities-current-pill {
  display: inline-flex;
  align-items: center;
  min-height: 36px;
  padding: 0 13px;
  border-radius: 999px;
  color: var(--primary-dark);
  background: var(--primary-soft);
  border: 1px solid var(--line-strong);
  font-size: .76rem;
  font-weight: 900;
  letter-spacing: .04em;
}

.given-activities-main {
  flex: 1 1 auto;
  min-height: 0;
  overflow: auto;
  overscroll-behavior: contain;
  padding: clamp(16px, 3vw, 34px);
}

.given-activities-main > * {
  width: min(1240px, 100%);
  margin-inline: auto;
}

.given-activities-welcome {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 22px;
  padding: clamp(18px, 3vw, 30px);
  border: 1px solid var(--line);
  border-radius: 24px;
  background: linear-gradient(135deg, var(--card), color-mix(in srgb, var(--primary-soft) 38%, var(--card)));
  box-shadow: var(--shadow);
}

.given-activities-welcome h2 {
  margin-bottom: 8px;
  font-size: clamp(1.35rem, 2.5vw, 2.1rem);
}

.given-activities-welcome p {
  max-width: 760px;
  margin: 0;
  color: var(--muted);
  line-height: 1.6;
}

.given-activities-eyebrow {
  display: block;
  margin-bottom: 8px;
  color: var(--primary);
  font-weight: 900;
  font-size: .74rem;
  letter-spacing: .12em;
  text-transform: uppercase;
}

.given-activities-stat {
  flex: 0 0 112px;
  display: grid;
  place-items: center;
  align-content: center;
  min-height: 104px;
  border-radius: 22px;
  background: var(--solid-card);
  border: 1px solid var(--line);
}

.given-activities-stat strong {
  font-size: 2rem;
  line-height: 1;
  color: var(--primary);
}

.given-activities-stat span {
  margin-top: 6px;
  color: var(--muted);
  font-size: .78rem;
  font-weight: 800;
}

.given-activities-controls {
  margin-top: 18px;
  padding: 14px;
  border: 1px solid var(--line);
  border-radius: 20px;
  background: var(--card);
}

.given-activities-filter-row {
  justify-content: space-between;
  gap: 12px;
  margin-top: 12px;
}

.given-activities-filter-row .lesson-library-search {
  flex: 1 1 420px;
}

.given-activities-filter-row select {
  min-width: 180px;
}

.given-activities-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 280px), 1fr));
  gap: 16px;
  margin-top: 16px;
  padding-bottom: 26px;
}

.given-activity-card {
  min-width: 0;
  border: 1px solid var(--line);
  border-radius: 22px;
  overflow: hidden;
  background: var(--solid-card);
  box-shadow: var(--shadow);
}

.given-activity-card-open {
  width: 100%;
  height: 100%;
  min-width: 0;
  padding: 0;
  border: 0;
  color: inherit;
  background: transparent;
  text-align: left;
  cursor: pointer;
}

.given-activity-card-open:hover .given-activity-card-cta,
.given-activity-card-open:focus-visible .given-activity-card-cta {
  color: var(--primary);
  transform: translateX(3px);
}

.given-activity-card-top {
  justify-content: space-between;
  gap: 12px;
  min-height: 86px;
  padding: 18px;
  background:
    linear-gradient(135deg, color-mix(in srgb, var(--primary-soft) 88%, var(--solid-card)), color-mix(in srgb, var(--success-soft) 55%, var(--solid-card)));
}

.given-activity-order {
  font-size: 2rem;
  font-weight: 1000;
  color: var(--primary);
  letter-spacing: -.05em;
}

.given-activity-type {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 7px 10px;
  border: 1px solid var(--line-strong);
  border-radius: 999px;
  color: var(--text);
  background: color-mix(in srgb, var(--solid-card) 82%, transparent);
  font-size: .72rem;
  font-weight: 900;
}

.given-activity-card-body {
  min-width: 0;
  padding: 18px;
}

.given-activity-term {
  color: var(--primary);
  font-size: .72rem;
  font-weight: 900;
  text-transform: uppercase;
  letter-spacing: .06em;
}

.given-activity-card-body h3 {
  margin: 7px 0 8px;
  overflow-wrap: anywhere;
}

.given-activity-card-body p {
  display: -webkit-box;
  overflow: hidden;
  min-height: 3.9em;
  margin: 0 0 14px;
  color: var(--muted);
  line-height: 1.55;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
}

.given-activity-card-meta {
  justify-content: space-between;
  gap: 10px;
  padding-top: 12px;
  border-top: 1px solid var(--line);
  color: var(--muted);
  font-size: .76rem;
  font-weight: 700;
}

.given-activity-card-cta {
