}

.given-activity-viewer-header h2 {
  margin: 4px 0 6px;
  overflow-wrap: anywhere;
}

.given-activity-viewer-header p {
  max-width: 760px;
  margin: 0;
}

.given-activity-viewer-meta {
  color: var(--primary);
