/* ---------- Needs Attention ---------- */
.needs-attention-admin {
  min-width: 0;
}

.needs-attention-heading,
.given-activities-admin-heading,
.device-qa-heading {
  justify-content: space-between;
  gap: 18px;
  margin-bottom: 16px;
}

.needs-attention-heading > div,
.given-activities-admin-heading > div,
.device-qa-heading > div {
  min-width: 0;
}

.needs-attention-summary {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
  margin-bottom: 14px;
}

.needs-attention-summary button {
  display: grid;
  gap: 5px;
  min-width: 0;
  padding: 16px;
