  color: inherit;
  background: var(--solid-card);
  text-align: left;
  cursor: pointer;
}

.needs-attention-summary button:hover,
.needs-attention-summary button:focus-visible {
  border-color: var(--primary);
  box-shadow: 0 0 0 3px var(--primary-soft);
}

.needs-attention-summary strong {
  color: var(--primary);
  font-size: 1.75rem;
  line-height: 1;
}

.needs-attention-summary span {
  color: var(--muted);
  font-size: .77rem;
  font-weight: 800;
}

.needs-attention-toolbar,
.device-qa-controls,
.given-activity-form-grid,
.given-activity-link-grid {
  display: grid;
  gap: 10px;
}

.needs-attention-toolbar {
  grid-template-columns: minmax(180px, 1.2fr) minmax(150px, .8fr) minmax(190px, .9fr);
  margin-bottom: 10px;
}

.needs-attention-toolbar label,
.device-qa-controls label,
.given-activity-form-grid label,
.given-activity-link-grid label {
  display: grid;
  gap: 6px;
  min-width: 0;
  color: var(--muted);
  font-size: .78rem;
  font-weight: 800;
}

.needs-attention-list {
  display: grid;
  gap: 10px;
  margin-top: 14px;
}

.needs-attention-card {
  display: grid;
  grid-template-columns: minmax(220px, 1.15fr) minmax(250px, 1.7fr) minmax(190px, .9fr) auto;
  align-items: center;
  gap: 14px;
  min-width: 0;
  padding: 14px;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: var(--solid-card);
}

.needs-attention-student {
  gap: 10px;
  min-width: 0;
}

.needs-attention-avatar {
  display: grid;
  place-items: center;
  flex: 0 0 42px;
  width: 42px;
  height: 42px;
  border-radius: 14px;
  color: white;
  background: linear-gradient(135deg, var(--primary), #06b6d4);
  font-weight: 1000;
}

.needs-attention-student > div:last-child {
  min-width: 0;
}

.needs-attention-student strong,
.needs-attention-student small {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.needs-attention-student small,
.needs-attention-meta {
  color: var(--muted);
  font-size: .76rem;
}

.needs-attention-flags {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  min-width: 0;
}

.needs-flag {
  display: inline-flex;
  align-items: center;
  min-height: 28px;
  padding: 4px 9px;
  border: 1px solid var(--line);
  border-radius: 999px;
  font-size: .72rem;
  font-weight: 900;
}

.needs-flag.lacking {
  color: #b91c1c;
  border-color: #fecaca;
  background: #fef2f2;
}

.needs-flag.term-status {
  color: #92400e;
  border-color: #fde68a;
  background: #fffbeb;
}

.needs-flag.no-project {
  color: #1d4ed8;
  border-color: #bfdbfe;
  background: #eff6ff;
}

.needs-flag.inactive {
  color: #6b21a8;
  border-color: #e9d5ff;
  background: #faf5ff;
}

[data-theme="dark"] .needs-flag.lacking { color: #fecaca; border-color: rgba(248,113,113,.35); background: rgba(127,29,29,.34); }
[data-theme="dark"] .needs-flag.term-status { color: #fde68a; border-color: rgba(251,191,36,.35); background: rgba(120,53,15,.34); }
[data-theme="dark"] .needs-flag.no-project { color: #bfdbfe; border-color: rgba(96,165,250,.35); background: rgba(30,58,138,.32); }
[data-theme="dark"] .needs-flag.inactive { color: #e9d5ff; border-color: rgba(192,132,252,.35); background: rgba(88,28,135,.32); }

.needs-attention-meta {
  display: grid;
  gap: 4px;
  min-width: 0;
}

.needs-attention-actions {
  justify-content: flex-end;
  gap: 6px;
  flex-wrap: wrap;
}

/* ---------- Activities Given admin ---------- */
.given-activities-admin-head-actions {
  justify-content: flex-end;
  gap: 8px;
  flex-wrap: wrap;
}

.given-activities-admin-layout {
