  border-radius: 20px;
  background: var(--solid-card);
}

.given-activity-editor-head,
.given-activity-admin-list-head {
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 14px;
}

.given-activity-editor-head h4,
.given-activity-admin-list-head h4 {
  margin: 4px 0 0;
}

.given-activity-form-grid {
  grid-template-columns: repeat(2, minmax(0, 1fr));
  margin-bottom: 12px;
}

.given-activity-link-grid {
  grid-template-columns: minmax(130px, .5fr) minmax(220px, 1.5fr);
}

.given-activity-editor-card > label {
  display: grid;
  gap: 6px;
  color: var(--muted);
  font-size: .8rem;
  font-weight: 800;
}

.given-activity-editor-card textarea {
  resize: vertical;
