}

.given-activity-publish-row {
  justify-content: space-between;
  gap: 12px;
  margin-top: 14px;
}

.given-activity-admin-list {
  display: grid;
  gap: 9px;
  max-height: min(700px, 66dvh);
  overflow: auto;
  padding-right: 2px;
}

.given-activity-admin-row {
  display: grid;
  grid-template-columns: 48px minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
