}

.given-activity-visibility {
  flex: 0 0 auto;
  padding: 4px 7px;
  border-radius: 999px;
  font-size: .66rem;
  font-style: normal;
  font-weight: 900;
  text-transform: uppercase;
}

.given-activity-visibility.published {
