}

[data-theme="dark"] .given-activity-visibility.published { color: #bbf7d0; background: rgba(22,101,52,.45); }
[data-theme="dark"] .given-activity-visibility.draft { color: #fde68a; background: rgba(120,53,15,.46); }

.given-activity-admin-actions {
  justify-content: flex-end;
  gap: 5px;
  flex-wrap: wrap;
}

/* ---------- Device QA ---------- */
.device-qa-controls {
  grid-template-columns: minmax(180px, 1.2fr) 100px 100px 130px minmax(180px, 1fr) auto;
  align-items: end;
  margin-bottom: 12px;
}

.device-qa-controls > button {
  align-self: end;
}

.device-qa-status-row {
  justify-content: space-between;
  gap: 12px;
  padding: 10px 12px;
  border: 1px solid var(--line);
  border-radius: 14px 14px 0 0;
  color: var(--muted);
  background: var(--card);
  font-size: .78rem;
}

#deviceQaOverflowStatus[data-status="success"] { color: var(--success); }
#deviceQaOverflowStatus[data-status="warning"] { color: var(--warning); }
#deviceQaOverflowStatus[data-status="error"] { color: var(--danger); }

.device-qa-viewport-shell {
  display: grid;
  place-items: start center;
  width: 100%;
  min-height: 420px;
  max-height: 74dvh;
  overflow: auto;
  padding: 18px;
  border: 1px solid var(--line);
  border-top: 0;
  border-radius: 0 0 18px 18px;
  background:
    linear-gradient(45deg, color-mix(in srgb, var(--line) 34%, transparent) 25%, transparent 25%, transparent 75%, color-mix(in srgb, var(--line) 34%, transparent) 75%),
    linear-gradient(45deg, color-mix(in srgb, var(--line) 34%, transparent) 25%, transparent 25%, transparent 75%, color-mix(in srgb, var(--line) 34%, transparent) 75%),
    color-mix(in srgb, var(--bg-2) 80%, var(--solid-card));
  background-position: 0 0, 12px 12px;
  background-size: 24px 24px;
}

.device-qa-viewport-stage {
  position: relative;
  flex: 0 0 auto;
  min-width: 0;
  min-height: 0;
  border-radius: 18px;
  box-shadow: 0 18px 60px rgba(0,0,0,.28);
}

.device-qa-frame {
  position: absolute;
  inset: 0 auto auto 0;
  display: block;
  border: 8px solid #0f172a;
  border-radius: 18px;
  background: #fff;
  transform-origin: top left;
}

/* Child iframe cleanup for QA preview. */
.device-qa-preview-runtime #adminBtn,
.device-qa-preview-runtime #installAppBtn,
.device-qa-preview-runtime #adminOverlay {
  display: none !important;
}

.device-qa-preview-runtime {
  overflow-x: hidden !important;
}

/* ---------- General dark-mode consistency ---------- */
[data-theme="dark"] .given-activities-header,
[data-theme="dark"] .given-activities-welcome,
[data-theme="dark"] .given-activities-controls,
[data-theme="dark"] .given-activity-card,
[data-theme="dark"] .given-activity-viewer-card,
[data-theme="dark"] .given-activity-link-card,
[data-theme="dark"] .given-activity-text-card,
[data-theme="dark"] .needs-attention-summary button,
[data-theme="dark"] .needs-attention-card,
[data-theme="dark"] .given-activity-editor-card,
[data-theme="dark"] .given-activity-library-card,
