/* v299 — Activities Given multi-attachment upload + gallery */
.given-activity-selected-files {
  display: grid;
  gap: 7px;
  margin-top: 10px;
}

.given-activity-selected-files:empty {
  display: none;
}

.given-activity-selected-files > span {
  display: grid;
  grid-template-columns: 30px minmax(0, 1fr);
  gap: 2px 9px;
  align-items: center;
  min-width: 0;
  padding: 9px 11px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: color-mix(in srgb, var(--solid-card) 90%, var(--primary-soft));
  color: var(--text);
  font-size: .82rem;
  font-weight: 800;
  overflow-wrap: anywhere;
}

.given-activity-selected-files > span b {
  grid-row: 1 / 3;
  display: grid;
  place-items: center;
  width: 30px;
  height: 30px;
  border-radius: 10px;
  background: var(--primary-soft);
  color: var(--primary-dark);
  font-size: .72rem;
}

.given-activity-selected-files > span small {
  min-width: 0;
  color: var(--muted);
  font-size: .7rem;
  font-weight: 700;
}

.given-activity-selected-files > span.existing {
  border-style: dashed;
}

.given-activity-attachment-viewer {
  display: flex;
  flex-direction: column;
  min-width: 0;
  min-height: 100%;
}

.given-activity-attachment-toolbar {
  flex: 0 0 auto;
  display: grid;
  grid-template-columns: minmax(112px, auto) minmax(0, 1fr) minmax(112px, auto);
  align-items: center;
  gap: 10px;
  padding: 12px 14px;
  border-bottom: 1px solid var(--line);
  background: color-mix(in srgb, var(--solid-card) 94%, transparent);
}

.given-activity-attachment-toolbar .ghost-btn {
  min-width: 0;
  white-space: nowrap;
}

.given-activity-attachment-position {
  display: grid;
  justify-items: center;
  min-width: 0;
  text-align: center;
}

.given-activity-attachment-position strong {
  color: var(--primary);
  font-size: .88rem;
}

.given-activity-attachment-position span {
  max-width: 100%;
  overflow: hidden;
  color: var(--muted);
  font-size: .72rem;
  font-weight: 700;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.given-activity-attachment-list {
  flex: 0 0 auto;
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
  padding: 9px 12px;
  border-bottom: 1px solid var(--line);
  background: color-mix(in srgb, var(--bg-2) 70%, var(--solid-card));
  overflow-x: hidden;
}

.given-activity-attachment-chip {
  display: grid;
  grid-template-columns: auto auto minmax(0, 1fr);
  align-items: center;
  gap: 5px;
  min-width: 0;
  max-width: min(260px, 100%);
  min-height: 34px;
  padding: 5px 9px;
  border: 1px solid var(--line);
  border-radius: 999px;
  color: var(--text);
  background: var(--solid-card);
  cursor: pointer;
}

.given-activity-attachment-chip b {
  color: var(--primary);
  font-size: .72rem;
}

.given-activity-attachment-chip small {
  overflow: hidden;
  font-size: .7rem;
  font-weight: 800;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.given-activity-attachment-chip.active {
  border-color: color-mix(in srgb, var(--primary) 55%, var(--line));
  background: var(--primary-soft);
  box-shadow: 0 0 0 2px color-mix(in srgb, var(--primary) 12%, transparent);
}

.given-activity-single-attachment-label {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
  padding: 10px 14px;
  border-bottom: 1px solid var(--line);
  background: color-mix(in srgb, var(--solid-card) 94%, transparent);
}

.given-activity-single-attachment-label strong {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.given-activity-attachment-stage {
  flex: 1 1 auto;
  min-width: 0;
  min-height: 0;
  overflow: auto;
  overflow-x: hidden;
}

.given-activity-attachment-stage .given-activity-image-wrap {
  min-height: min(520px, calc(100dvh - 260px));
}

.given-activity-attachment-stage .given-activity-image-wrap img {
  max-width: min(100%, 1100px);
  max-height: calc(100dvh - 280px);
}

[data-theme="dark"] .given-activity-selected-files > span,
[data-theme="dark"] .given-activity-attachment-toolbar,
[data-theme="dark"] .given-activity-single-attachment-label,
[data-theme="dark"] .given-activity-attachment-chip {
  border-color: rgba(148, 163, 184, .2);
}

[data-theme="dark"] .given-activity-selected-files > span {
  background: rgba(15, 23, 42, .62);
}

[data-theme="dark"] .given-activity-attachment-list {
  background: rgba(2, 6, 23, .34);
}

[data-theme="dark"] .given-activity-attachment-chip {
  background: rgba(15, 23, 42, .72);
}

[data-theme="dark"] .given-activity-attachment-chip.active {
  background: rgba(30, 64, 175, .3);
  border-color: rgba(96, 165, 250, .55);
}

@media (max-width: 620px) {
  .given-activity-attachment-toolbar {
    grid-template-columns: 92px minmax(0, 1fr) 92px;
    gap: 6px;
    padding: 9px;
  }

  .given-activity-attachment-toolbar .ghost-btn {
    min-height: 40px;
    padding-inline: 8px;
    font-size: .73rem;
  }

  .given-activity-attachment-position span {
    font-size: .65rem;
  }

  .given-activity-attachment-list {
    gap: 6px;
    padding: 7px 8px;
  }

  .given-activity-attachment-chip {
