    border-radius: 12px;
  }

  .given-activity-attachment-stage .given-activity-image-wrap {
    min-height: calc(100dvh - 300px);
    padding: 10px;
  }

  .given-activity-attachment-stage .given-activity-image-wrap img {
    max-height: calc(100dvh - 300px);
  }

  .given-activity-selected-files > span {
    font-size: .76rem;
  }
}


