/* v303 — image fit/zoom viewer + PDF download action */
.given-activity-viewer-download-btn.hidden {
  display: none !important;
}

.given-activity-attachment-stage .given-activity-image-wrap {
  position: relative;
  display: block !important;
  width: 100% !important;
  height: 100% !important;
  min-height: 0 !important;
  padding: 0 !important;
  overflow: hidden !important;
  background: color-mix(in srgb, var(--bg-2) 92%, #000 4%);
}

.given-activity-image-scroll {
  width: 100%;
  height: 100%;
  min-width: 0;
  min-height: 0;
  overflow: auto;
  overscroll-behavior: contain;
  -webkit-overflow-scrolling: touch;
  touch-action: pan-x pan-y pinch-zoom;
  scrollbar-width: thin;
}

.given-activity-image-canvas {
  box-sizing: border-box;
  display: flex;
  align-items: center;
  justify-content: center;
  width: max-content;
  min-width: 100%;
  height: max-content;
  min-height: 100%;
  padding: 12px;
}

.given-activity-image-scroll.is-zoomed .given-activity-image-canvas {
  align-items: flex-start;
  justify-content: flex-start;
}

.given-activity-attachment-stage .given-activity-image-wrap img {
  display: block;
  flex: 0 0 auto;
  width: auto;
  height: auto;
  max-width: none !important;
  max-height: none !important;
  margin: auto;
  object-fit: contain;
  transform: none !important;
  cursor: zoom-in;
  -webkit-touch-callout: default;
}

.given-activity-image-scroll.is-zoomed .given-activity-image-wrap img {
  margin: 0;
  cursor: grab;
}

.given-activity-image-zoom-controls {
  position: absolute;
  z-index: 4;
  right: 12px;
  bottom: 12px;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  min-height: 38px;
  padding: 4px;
  border: 1px solid color-mix(in srgb, var(--line-strong) 85%, transparent);
  border-radius: 999px;
  background: color-mix(in srgb, var(--solid-card) 88%, transparent);
  box-shadow: 0 8px 24px rgba(2, 6, 23, .18);
  backdrop-filter: blur(12px);
}

.given-activity-image-zoom-btn,
.given-activity-image-fit-btn {
  display: inline-grid;
  place-items: center;
  min-width: 30px;
  height: 30px;
  padding: 0 8px;
  border: 0;
  border-radius: 999px;
  color: var(--text);
  background: transparent;
  font: inherit;
  font-size: .78rem;
  font-weight: 900;
  cursor: pointer;
}

.given-activity-image-zoom-btn {
  width: 30px;
  padding: 0;
  font-size: 1.05rem;
}

.given-activity-image-fit-btn {
  color: var(--primary-dark);
  background: var(--primary-soft);
}

.given-activity-image-zoom-btn:hover,
.given-activity-image-zoom-btn:focus-visible,
.given-activity-image-fit-btn:hover,
.given-activity-image-fit-btn:focus-visible {
  outline: none;
  background: color-mix(in srgb, var(--primary-soft) 76%, var(--solid-card));
}

.given-activity-image-zoom-btn:disabled {
  opacity: .38;
  cursor: default;
}

.given-activity-image-zoom-value {
  min-width: 38px;
  color: var(--muted);
  font-size: .68rem;
  font-weight: 900;
  text-align: center;
}

[data-theme="dark"] .given-activity-image-zoom-controls {
  border-color: rgba(148, 163, 184, .28);
  background: rgba(15, 23, 42, .86);
  box-shadow: 0 10px 30px rgba(0, 0, 0, .35);
}

[data-theme="dark"] .given-activity-image-fit-btn {
  color: #bfdbfe;
  background: rgba(30, 64, 175, .38);
}

@media (max-width: 820px) {
  .given-activity-image-canvas {
    padding: 8px;
  }

